INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(8, '위대한 잇잘드 모자', '이 모자는 당신이 마법사라는 사실을 말하는 정도가 아니라 아주 크게 외쳐 댑니다. 특히 몰래 빠져나가려 할 때요. 경고: 원치 않는 영웅적인 퀘스트를 끌어들일 수 있습니다.'),
(10, '게임 마스터의 파멸의 빗자루', '100억 명의 사람들을 없앨 권리가 당신에게 있는지 의문을 제기하는 사람들이 있을지도 모릅니다. 하지만 그 의미를 이해하는 사람들은 당신에게 그들을 살려둘 권리조차 없다는 것을 깨닫습니다.'),
(41, '[구버전] 신병의 허리띠', '위습은 칼림도어의 숲에 사는 고대 자연의 정령입니다. 전설에 따르면 위습은 실제로 나이트 엘프의 육체에서 벗어난 영혼이라고 하지만 아직 확인된 바는 없습니다.\\N'),
(115, '프레키세 자물쇠 키린델', '차분하고 체계적인 자물쇠 따기 연습에 안성맞춤입니다.'),
(734, '더 이상 사용되지 않는 말라카이의 메달', '이 쇠 원반에는 다음과 같은 글자가 찍혀 있습니다: "보병 말라카이 스톤"'),
(751, '한여름 황혼의 셔츠', '해 질 녘까지 숯불을 돌보고 불씨를 지키는 이들이 입습니다.'),
(956, '더 이상 사용되지 않는 지역 트리거 플래그 - Jasperlode 광산', '공식 \'벽옥 광산까지 갔는데 겨우 이 허접한 셔츠 하나 받았다\' 티셔츠'),
(958, '더 이상 사용되지 않는 지역 트리거 플래그 - Darkhollow Mine', '공식 \'다크할로우 광산까지 갔는데 겨우 이 허접한 셔츠 하나 받았다\' 티셔츠'),
(960, '더 이상 사용되지 않는 영역 트리거 플래그 - Fargodeep', '공식 \'파고딥 광산까지 갔는데 겨우 이 허접한 셔츠 하나 받았다\' 티셔츠'),
(964, '[사용 중단] 빨간색 리넨 셔츠', '성공적인 모습을 보여주기 위한 옷차림, 적어도 노숙자처럼 보이지 않도록 말이죠.'),
(1041, '검은 늑대 뿔피리', '탈것 소환하는 법을 배웁니다.'),
(1078, '더 이상 사용되지 않는 레이크샤이어의 영장', '존경받는 행정관 솔로몬의 서명이 적혀 있습니다.'),
(1122, '더 이상 사용되지 않는 흰 종마의 부적', '백마를 소환해 탈것으로 이용합니다.'),
(1123, '더 이상 사용되지 않는 핀토의 부적', '얼룩말을 소환해 탈것으로 이용합니다.'),
(1124, '더 이상 사용되지 않는 팔로미노의 부적', '황금빛 말을 소환해 탈것으로 이용합니다.'),
(1125, '더 이상 사용되지 않는 악몽의 아뮬렛', '악몽마를 소환해 탈것으로 이용합니다.'),
(1134, '회색 늑대 뿔피리', '야생에서 맹렬하고 충성스러운 동반자.'),
(1217, '알 수 없는 보상', '어떤 보상을 받게 될지 알 수 없습니다...'),
(1281, '더 이상 사용되지 않는 Quiver(테스트)', '원거리 공격 테스트용'),
(1323, '더 이상 사용되지 않음 [PH] 조리법: 개복치 구이', '요리 전문기술 조리법으로 사용될 예정입니다.'),
(1350, '더 이상 사용되지 않는 육각형 인형', '해진 인형 곳곳에 수많은 저주가 꿰매져 있습니다.'),
(1492, '더 이상 사용되지 않는 조리법: 멀록 지느러미 수프', '요리 전문기술 조리법으로 사용될 예정입니다.'),
(1599, '더 이상 사용되지 않음 [PH] 레시피: 좀비 주스', '요리 전문기술 조리법으로 사용될 예정입니다.'),
(2003, '더 이상 사용되지 않는 큰 화살통', '커다란 화살통'),
(2197, '드워프 전투 로압', '단순한 음식이 아닙니다. 드워프 문화가 얼마나 질긴지를 증명하는 물건이죠. 현명하게 사용하거나, 그냥 돌을 깨는 데 써도 됩니다.'),
(2410, '연기 나는 횃불', '흔들리지만 믿음직한 불꽃을 내는 튼튼한 나무 횃불입니다.'),
(2460, '언어의 비약', '미구현'),
(2556, '조제법: 언어의 비약', '미구현'),
(2714, '몬스터 - 등불 - 사각 아이템', '숲 속에서 길을 잃지 않을 만큼 밝습니다.'),
(2755, '가시덤불 골짜기의 푸른 언덕', '헤멧 네싱워리 지음'),
(2789, '더 이상 사용되지 않는 구부러진 구리 자물쇠 따기', '난이도 25의 자물쇠를 엽니다.'),
(2790, '더 이상 사용되지 않는 직선 구리 자물쇠 따기', '난이도 50의 자물쇠를 엽니다.'),
(2791, '더 이상 사용되지 않는 고급 구리 자물쇠 따개', '난이도 75의 자물쇠를 엽니다.'),
(2792, '더 이상 사용되지 않는 낡은 청동 자물쇠 따개', '난이도 100의 자물쇠를 엽니다.'),
(2884, '고블린의 팔티 핏즈렐', '큰 재미를 위한 작은 불꽃 하나.'),
(2929, '썩은 무덤 가루', '도적이 독 제조에 사용하는 재료입니다.'),
(2932, '고통의 덩굴', '도적이 독 제조에 사용하는 재료입니다.'),
(3122, '법전: 빛의 권능: 보호막 III', '빛의 권능: 보호막 주문을 배웁니다. (3 레벨)'),
(3249, '창조된 테스트 아이템', '창조된 아이템 테스트용 물품입니다.'),
(3744, '혈석 펜던트', '퀘스트 아이템'),
(3762, '사서의 가방', '더 큰 모험을 위한 더 큰 주머니!'),
(4158, '마법서: 카드가의 자물쇠 해제 III', '당신은 마법적인 부분만 이해하고 있어요. 나머지 부분을 이해하려면 도움이 필요할 거예요.'),
(4200, '흑마법서: 제물 III', '제물 주문을 배웁니다. (3 레벨)'),
(4620, '더 이상 사용되지 않는 낙서 메모', '낡은 쪽지에 분필로 무언가 적혀 있습니다...'),
(4981, '아그몬드의 허리 주머니', '모험가의 최고의 친구 - 이 녀석은 소매치기를 못 해!'),
(5047, '해골 모양 포장지', '40레벨 이상의 플레이어만 이 상자를 열 수 있습니다.'),
(5049, '자물쇠 달린 포장지', '자물쇠 따기 숙련도 150 이상만 열 수 있습니다.'),
(5235, '연금술사의 마법봉', '한때 불타는 칼날단의 일원이 사용했던 조잡한 마법봉입니다.'),
(5372, '더 이상 사용되지 않는 빛나는 축소된 해골', '이 해골의 눈이 밝게 빛납니다.'),
(5378, '셰인 테스트(DELETE ME)', '스톤헨지')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(5380, '엘리자에게 보내는 봉인된 편지', '아우버다인의 엘리자에게 보내는 봉인된 편지'),
(5381, '발툴에게 보내는 봉인된 편지', '수취인이 발툴 섀도스트라이크로 되어 있는 봉인된 편지'),
(5517, '작은 청동 열쇠', '마법사가 마법 주문을 외울 때 필요한 물건입니다.'),
(5518, '작은 철제 열쇠', '마법사가 마법 주문을 외울 때 필요한 물건입니다.'),
(5546, '메디브의 코지 파자맛', '카라잔의 탑을 최초로 정복한 이들이 착용한 승리의 상징입니다.'),
(5663, '붉은 늑대 뿔피리', '탈것 소환하는 법을 배웁니다.'),
(5857, '노움 상품', '상품이 들어 있는 상자'),
(5858, '고블린 축제 상자', '경품 추첨에 참여하세요!'),
(5896, '테라모어 경비병 메달 미사용', '이름이 새겨져 있습니다: 뮤렌 맥피어'),
(5916, '노움 카메라 열쇠', '아직 구현되지 않았습니다.'),
(5937, '고블린 카메라 열쇠', '아직 구현되지 않았습니다.'),
(6216, '신비한 가루', '마법부여사가 마법을 부여하기 위해 필요한 재료입니다.'),
(6343, '주문식: 가슴보호구 임시 마법부여 - 정신력', '가슴보호구에 일시적으로 마법을 부여해 60분 동안 착용자의 정신력을 3만큼 증가시키는 법을 배웁니다.'),
