(36500, '순피레 여우', '태양불꽃 여우의 황금빛 털이 빛나며, 가는 곳마다 따뜻함을 전합니다.'),
(36501, '귤빛 바람 뱀', '햇빛과 산들바람의 정수를 품은 듯 하늘에 고요히 떠다닙니다...'),
(36502, '어둠 바람 뱀', '우아하면서도 신비로운 기운으로 하늘을 누비는 어둠의 바람뱀을 보십시오.'),
(36503, '에메랄드빛 바람 뱀', '눈부신 녹색 비늘을 지닌 에메랄드 바람뱀이 자연의 평온함을 몸소 보여 주듯 하늘을 우아하게 춤춥니다.'),
(36504, '하늘빛 바람 뱀', '찬란한 푸른 비늘을 두르고 고요한 우아함으로 하늘을 활공하며 지나간 자리에 평온을 남깁니다.'),
(36505, '진홍빛 사벨캇 새끼', '불꽃 같은 털에 아제로스 야생을 누비는 젊은 모험심을 담은 활기찬 동료입니다.'),
(36506, '얼라이언스 사자 새끼', '용기와 단결을 조그맣게 빚어 놓은 듯한 사자 새끼입니다. 자랑스러운 혈통을 상징하는 황금빛 갈기를 지녔습니다.'),
(36507, '스폿', '독특한 얼룩무늬를 지닌 장난기 많은 고양이 동료로, 모험에 야생의 멋을 더해 줍니다.'),
(36508, '황혼 프오스', '깊고 매혹적인 푸른 털을 두른 작은 어둠의 덩어리입니다. 귀여운 이 동료가 모험에 신비로운 매력을 더해 줍니다.'),
(36509, '검은 판스엘 새끼', '비단처럼 부드러운 털과 호기심 가득한 눈을 지닌 작은 그림자 사냥꾼입니다. 대담한 모험에 귀여움을 더해 줍니다.'),
(36510, '황갈색', '부드러운 황갈색 털과 장난스러운 몸짓을 지닌 사랑스러운 새끼로, 아제로스 여행에서 마음을 따뜻하게 해 줄 동료입니다.'),
(36511, '밤호랑이 새끼', '엘룬은 달빛이 비치는 밤에 그림자 속으로 녹아들 수 있도록 밤호랑이의 털을 은빛과 검은빛으로 만들었습니다.'),
(36512, '눈 새끼', '던 모로 근처의 두꺼운 눈은 사냥을 배우는 눈표범 새끼들에게 훌륭한 위장이 됩니다.'),
(36513, '스타응레톨느 호랑이 새끼', '독특한 줄무늬를 지닌 활기차고 정 많은 새끼입니다. 가시덤불 골짜기의 야생미를 작게 담아 놓은 듯합니다.'),
(36514, '프롯트사벨 새끼', '매혹적인 줄무늬가 새겨진 눈처럼 하얀 털을 가진 사랑스러운 동료로, 아제로스의 겨울 풍경을 곁에 데려옵니다.'),
(36515, '치이타흐 새끼', '장난기 많은 이 고양이 새끼들은 불모의 땅에서 서로를 몰래 뒤쫓으며 사냥 기술을 연습합니다.'),
(36516, '밤색', '가장 푹신한 베개와 견줄 만큼 풍성한 꼬리를 지닌 다람쥐입니다. 숲의 귀여움 그 자체로 가는 곳마다 즐거움을 퍼뜨립니다.'),
(40002, '뱀 가방', '뱀들이 화난 듯 쉿쉿거리며 자루 안에서 몸부림친다. 오래 가둬둘 수는 없을 것이다.'),
(40077, '빈 와인병', '탈라시안 항구 VI'),
(40078, '켈탈라스의 기념품', '좋았던 시절을 떠올리게 한다.'),
(41011, '나무로 만든 그리핀 조각', '그리핀 형상에는 "아빠를 위해."라는 글귀가 새겨져 있습니다.'),
(41027, '교수형 집행인의 약탈자 일지', '<견고한 금속 자물쇠가 이 항해일지를 단단히 잠가줍니다.>'),
(41049, '금이 간 양철 부츠', '균열 덕분에 공기역학적으로 유리하다.'),
(41050, '행운의 주머니', '획득하는 모든 골드량을 5% 증가시켜 줍니다. 정말 그럴까요?'),
(41059, '위조 셸코인', '이것들이 가치가 있을지 의심스럽군요.'),
(41062, '엿보는 눈알', '당신의 약점을 알고 있습니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(41063, '의사의 실험복', '이 물건에 묻은 얼룩에 대해 굳이 따지지 않는 게 현명할 것이다.'),
(41077, '광신적 헌신의 두건, 이쉬골라르', '덩굴손이 머리 뒤쪽으로 파고드는 느낌이 듭니다.'),
(41132, '변색된 메이스', '칼자루에는 L.B.라는 이니셜이 새겨져 있습니다.'),
(41294, '고급 방목 알터랙 예티 가죽', '자연에서 채취한 공정 무역 제품!'),
(41295, '길 잃은 엑카바션 피크아케', '바위와 돌이라면 너무나 익숙합니다.'),
(41364, '가벼운 모네이 가방', '무겁게 느껴지지 않습니다.'),
(41366, '거대한 붉은십자군 루비', '주먹 안에 쏙 들어옵니다.'),
(41367, '새겨진 보석', '표면이 갈라지고 쉽게 부서질 듯합니다.'),
(41395, '순백의 다이아몬드 목걸이', '세월의 시험을 견뎌 냈습니다.'),
(41401, '부서진 화살', '진정한 사랑을 찾고 싶어요.'),
(41402, '파타리티의 시압비 콘트락트', '흥미롭군요. 반대편을 읽으면 어떻게 될까요?'),
(41415, '메디브의 홀', '홀에서 강렬한 에너지가 뿜어져 나오는 것이 느껴집니다. 본래의 진정한 목적을 위해 사용해 달라고 부르는 듯합니다.'),
(41427, '결의의 텟티모니', '브라이트하트 사부의 문하에 들어섰음을 증명합니다.'),
(41428, '알치에미칼 콤프아우느드스의 올델', '길게 적힌 약초와 기타 재료 목록 아래, \'의뢰인\' 항목에 재러드 보스라는 이름이 적혀 있습니다.'),
(49000, '바콘 퀘스트의 문양', '이 도전에서는 레벨을 올리는 일이 말 그대로 \'돼지 같은\' 일입니다. 경험치는 오직 멧돼지와의 전투에서만 얻을 수 있습니다!'),
(50000, '캐릭터 이름 변경', '사용하려면 오른쪽 클릭하세요. 다음 로그인 시 새로운 이름을 선택하라는 안내가 표시됩니다.'),
(50004, '휴대용 주머니 차원', '내용물이 아무리 무거워도 이 가방의 모양과 무게는 전혀 변하지 않는 듯합니다.'),
(50005, '야전수리로봇 75B', '펼치면 손상된 장비를 수리하고 불필요한 물건을 매입하는 야전수리로봇이 됩니다.'),
(50007, '포원 노새', '당신의 온갖 소지품을 싣고 어디든 함께합니다.'),
(50009, '기계식 경매인', '오른쪽 클릭하면 C.L.U.C.K.를 소환합니다.'),
(50011, 'MOLL-E 원격 우편 단말기', '이동식 대형 우편 및 문서 처리 장치.'),
(50013, '뼈 골렘', '뼈 골렘은 온통 뼈로 만들어지고 언데드의 수액으로 움직이는 치명적인 언데드 피조물입니다.'),
(50014, '블리첸', '즐거운 겨울맞이 축제 보내세요!'),
(50015, '피 묻은 동전', '몇몇 피비린내 나는 행사에서 사용하는 지역 화폐입니다.'),
(50016, '부서진 만남의 돌', '전혀 마법이 깃든 물건처럼 보이지 않습니다... 목걸이는 긁히고 부서져 있습니다.'),
(50017, '환영: 블러드 엘프', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50019, '달빛야수 새끼', '달빛야수는 엘룬의 축복을 받아 가는 곳마다 자연의 은총을 퍼뜨립니다. 축제 분위기에 들뜬 이 새들은 언제나 춤출 준비가 되어 있습니다.'),
(50020, '마법 머핀', '조심하세요. 너무 커지면 옷이 맞지 않을 수도 있습니다.'),
(50021, '수상한 병', '조금 작아진 기분이 들 겁니다...'),
(50038, '붉은 마법매듭 휘장', '멋을 아는 마법사를 위한 대담한 색상입니다.\\N'),
(50044, '황금 마법매듭 휘장', '고급스러움을 더한 황금빛입니다.\\N'),
(50046, '여름의 의복', '춤을 추고 싶은 충동이 듭니다.'),
(50049, '보물사냥꾼의 횃불', '어둠 속에서도 상자를 놓치지 마세요!'),
(50050, '스피디의 선물 상자: 레벨 10', '여정을 든든하게 이어가도록 스피디가 준비한 작은 선물입니다.\\N'),
(50051, '스피디의 선물 상자: 레벨 20', '계속 힘내세요! 스피디가 끈기에 보답합니다.\\N'),
(50052, '스피디의 선물 상자: 레벨 30', '천천히 꾸준히 가는 자가 이깁니다. 그 사실을 증명하는 선물입니다.\\N'),
(50053, '스피디의 선물 상자: 레벨 40', '아주 잘하고 있어요! 계속 나아가는 당신을 스피디가 응원합니다.\\N'),
(50054, '스피디의 선물 상자: 레벨 50', '인내는 미덕이며, 스피디의 보상이 그 증거입니다.\\N'),
(50055, '스피디의 선물 상자: 레벨 60', '축하합니다! 천천히 꾸준히 나아간 보람이 있었군요. 정당하게 얻은 상을 즐기세요.\\N'),
(50056, '도시 수호자의 메달', '당신을 수도로 이동시킵니다. 이 아이템을 사용하려면 도시 수호자가 되어야 합니다.'),
(50058, '검은 새끼돼지', '느긋한 성격의 여행 동료입니다.'),
(50066, '강철 기계식 스트라이더', '가장 치열한 전투도 견딜 수 있도록 제작된 놀라운 기계입니다.'),
(50067, '알비노 뱀', '키린 토 마법사들이 즐겨 데리고 다니는 파충류입니다. 정말 뱀인지, 아니면 전혀 다른 무언가인지 궁금하게 만듭니다.'),
(50068, '초록물뱀', '상선에 실려 스파크워터 항구로 들어온 이 수명이 짧은 파충류는 항구 주민들에게 해충 취급을 받습니다.'),
(50069, '스칼렛 스네이크', '대담한 암살자들은 때때로 이 작은 생물을 잡아 강력한 독을 무기에 바르는 데 사용합니다.'),
(50070, '청동 새끼', '청동 새끼용은 기묘한 사건을 계기로 탈출하기 전까지 시간 속에 길을 잃고 있었습니다.'),
(50073, '그레이 톨스트라이더', '과묵하고 관찰력이 뛰어나며 어떤 환경에도 잘 적응하는 생물입니다.'),
(50074, '핑크 탈스트라이더', '활기차고 장난기 많은 새로, 가는 곳마다 즐거움을 퍼뜨립니다.'),
(50075, '퍼플 톨스트라이더', '다크문 축제에서 실수로 풀려났지만, 뜻밖에도 꽤 튼튼한 탈것이 되었습니다.'),
(50076, '터쿼이즈 톨스트라이더', '열대 바다처럼 밝은 깃털을 지닌 희귀하고 이국적인 새입니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(50077, '브라이트윙', '안녕, 친구! 브라이트윙은 네가 찾아오는 걸 정말 좋아해!'),
(50078, '다트 프로그', '두꺼비와 개구리는 트롤과 떼려야 뗄 수 없는 친구이자 독을 만들기에 훌륭한 재료입니다.'),
(50079, '섬개구리', '이 작은 친구는 여행에 따라나서려고 몰래 당신의 장화 속에 숨어들었습니다.'),
(50080, '독수리 부엉이', '많은 올빼미가 다르나서스의 높은 석조 건축물에 둥지를 틀고, 나이트 엘프의 도시에 들어오는 해충을 사냥합니다.'),
(50081, '솜꼬리토끼', '산솜꼬리토끼는 믿기 어려울 만큼 빠르게 가파른 비탈을 뛰어오를 수 있습니다.'),
(50082, '흰올빼미', '윈터스프링의 퍼볼그족은 이 위엄 있는 생물들의 눈부시게 하얀 깃털을 의식용으로 귀하게 여깁니다.'),
(50083, '푸른 새끼용', '다른 푸른 용군단 구성원들과 마찬가지로, 이 기발하고 작은 생명체들은 신비로운 마법에 대한 친화력을 보여줍니다.'),
(50084, '키린 토르 패밀리어', '그가 책에 그렇게 빠져있을 줄 누가 알았겠어?'),
(50085, '프로스트울프 고스트펍', '어린 늑대는 그 자리에 있으라는 말을 들었다. 먹잇감이 나타나기를 기다리며 지켜보았다. 하지만 너무 자존심이 세서 떠날 수 없었던 그녀는 슬며시 빠져나갔다. 이제 짐을 덜고 영원히 자유롭게 뛰어놀 수 있게 되었다.'),
(50086, '스트롬가드 타바드', '스트롬가드의 유산은 계속 살아 있습니다.\\N'),
(50087, '쿨 티라스의 타바드', '해군 사령부에 충성을 맹세한 자들의 색입니다.\\N'),
(50088, '테라모어 타바드', '테라모어 자체처럼 굳건합니다.\\N'),
(50089, '훔친 달라란 타바드', '달라란에서 몰래 가져온 기념품입니다.\\N'),
(50090, '스톰윈드의 하얀 타바드', '스톰윈드의 순수함을 담아, 왕국을 위해 쓰러진 용감한 영웅들을 기립니다.\\N'),
(50091, '블랙 마법매듭 타바드', '금지된 욕망의 향이 감도는 어둡고 신비로운 색입니다.\\N'),
(50092, '진홍색 군단의 문장', '불타는 목적을 품은 진홍빛입니다.\\N'),
(50093, '하스글렌의 타바드', '성스러운 땅을 지키는 신도들이 착용하는 하스글렌의 깃발입니다.\\N'),
(50094, '천 개의 진실의 검', '언젠가 검을 휘두를 수 있는 영웅들이 나타날 것이라는 예언이 있었다.'),
(50105, '스칼렛 [인간, 여성만 해당]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50106, '강령술사 I [인간]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50107, '나이트 엘프 헤어 염색약: 풀잎색', '대자연의 드리아드처럼 되고 싶은 이들을 위한 나뭇잎빛 초록색입니다.\\N'),
(50108, '나이트 엘프 헤어 염색약: 녹색', '자연의 영혼을 닮고 싶은 엘프에게 어울리는 차분하고 서늘한 녹색입니다.\\N'),
(50109, '나이트 엘프 헤어 염색약: 진녹색', '내면의 드루이드를 깨워 보세요... 아, 낮잠 잘 시간이군요...\\N'),
(50110, '나이트 엘프 헤어 염색약: 아쿠아마린', '달샘의 물처럼 맑은 청록빛입니다. 마음을 차분하게 해 주지만 비밀도 품고 있습니다.\\N'),
(50111, '나이트 엘프 헤어 염색약: 흰색', '흔히 생각하는 것과 달리, 흰 머리카락만으로 나이트 엘프의 나이를 짐작할 수는 없습니다.\\N'),
(50112, '나이트 엘프 헤어 염색약: 파란색', '잿빛 골짜기 하늘처럼 푸른빛입니다. 신비와 고대의 지혜가 함께 깃들어 있습니다.\\N'),
(50113, '나이트 엘프 헤어 염색약: 진한 파란색', '영원한 별빛이 비치는 땅에 잘 어울리는 짙고 어두운 파란색입니다.\\N'),
(50114, '나이트 엘프 헤어 염색약: 보라색', '꽃처럼 싱그럽고 선명한 보라색입니다!\\N'),
(50115, '인모 염색약: 검정색', '12시간 꼼짝없이 보초를 선 야간 경비병의 기분만큼이나 어둡습니다.\\N'),
(50116, '인모 염색약: 크러시드 가넷', '빛과 성별에 따라 짙은 적갈색이나 평범한 갈색으로 보입니다.\\N'),
(50117, '인모 염색약: 하바나 브라운', '구릿빛 갈색입니다. 광물을 캐든, 코볼트의 양초를 빼앗든 잘 어울립니다.\\N'),
(50118, '인모 염색약: 구리빛 반짝임', '밝게 타오르는 불꽃 같은 붉은색입니다. 음, 매콤하군요!\\N'),
(50119, '인모 염색약: 붉은빛이 도는 금발', '윤이 나는 짙은 적금빛입니다. 맨정신인 것보다는 낫지 않겠습니까?\\N'),
(50120, '인모 염색약: 해바라기 금발', '성당 광장의 지붕 위로 떠오르는 태양처럼 밝고 빛나는 정통 금발입니다.\\N'),
(50121, '사람 모발용 염색약: 비라인 허니', '찬란한 햇빛 같은 노란색입니다. 햇빛이 어떻게 생겼는지는 기억하시죠?\\N'),
(50122, '인모 염색약: 밀색 금발', '잿빛 금발입니다. 허리 통증만 뺀 서부 몰락지대의 수확철 같은 색이죠.\\N'),
(50123, '인모 염색약: 다크 애쉬 그레이', '수많은 전투를 겪고 목욕은 너무 적게 한 기사처럼 강철빛 회색입니다.\\N'),
(50124, '인모 염색약: 라이트 애쉬 그레이', '나이가 들수록 더욱 멋스러워지는 품위 있는 은빛입니다.\\N'),
(50125, '노움 헤어 염색약: 검정색', '마지막 \'통제된\' 폭발만큼이나 새까맣습니다.\\N'),
(50126, '그놈족 헤어 염색약: 초콜릿 브라운', '술에 취해 벌인 사고의 흔적 같은 갈색입니다.\\N'),
(50127, '노움 헤어 염색약: 애쉬 블론드', '반짝이고, 금발이고, 조금 지나치게 밝습니다.\\N'),
(50128, '노움 헤어 염색약: 다이아몬드 블론드', '푸른빛이 감도는 오팔빛 흰색입니다. 전도성이 있는 여러 액체가 떠오르네요. 설마 이걸 만드는 데 그런 걸 쓴 건 아니겠죠.\\N'),
(50129, '노움 헤어 염색약: 드림 퍼플', '영겁토록 파고 또 파야 할 갱도처럼 새까맣습니다.\\N'),
(50130, '노움 헤어 염색약: 루비 퓨전', '뜨겁고 붉으며, 환불은 절대 되지 않습니다.\\N'),
(50131, '노움 헤어 염색약: 스틸 블루', '최근의 \'혁신적인\' 발명에서 튄 불꽃처럼 옅은 은청색입니다.\\N'),
(50132, '노움 헤어 염색약: 퓨어 그린', '녹색입니다. 오염된 노움들 사이에서 요즘 가장 유행한다고 합니다.\\N'),
(50133, '노움 헤어 염색약: 빛나는 핑크', '분홍 머리를 보고 비웃을지도 모르지만, 다음 발명가 박람회에서는 누구보다 시선을 사로잡을 겁니다.\\N'),
(50134, '드워프 헤어 염색약: 구리빛 반짝임', '선명한 주황색입니다. 대장간보다 뜨겁고, 두 배는 더 고집스럽습니다.\\N'),
(50135, '드워프 헤어 염색약: 붉은빛이 도는 금발', '밤새 싸우게 만드는 드워프의 맥주처럼 황금빛이고 강렬합니다.\\N'),
(50136, '드워프 헤어 염색약: 진한 오렌지색', '불타는 듯한 붉은색입니다! 수염을 건드렸을 때 드워프의 성질보다 더 뜨겁습니다.\\N')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(50137, '드워프 헤어 염색약: 애쉬 블론드', '갱도의 바위처럼 옅은 회색이며, 그만큼이나 단단합니다.\\N'),
(50138, '드워프 헤어 염색약: 밝은 적갈색', '적갈색입니다. 백 년간 피를 묻힌 전투 도끼처럼 녹슨 빛이 납니다.\\N'),
(50140, '드워프 헤어 염색약: 카라멜', '금발도 갈색도 아닌 애매한 색입니다. 몇 잔 마시면 판단이 쉬워질지도...\\N'),
(50141, '드워프 헤어 염색약: 라이트 애쉬 그레이', '진정한 은회색입니다. 강철처럼 단단하고 우리가 파고드는 산맥처럼 억셉니다.\\N'),
(50142, '드워프 헤어 염색약: 다크 애쉬 그레이', '수많은 전쟁을 겪은 드워프 전사의 낡은 가죽처럼 짙은 잿빛 회색입니다.\\N'),
(50143, '트롤 헤어 염색약: 보라색', '왕족처럼 보이고 왕처럼 행동하세요. 아니면 저주받든가요. 선택은 당신 몫입니다.\\N'),
(50144, '트롤 헤어 염색약: 빨간색', '피처럼 붉습니다. 당장 전투에 나설 준비가 된 듯하군요. 아니면 그냥 화가 난 걸지도요. 어느 쪽이든 광전사처럼 보일 겁니다.\\N'),
(50145, '트롤 헤어 염색약: 오렌지색', '사막에서 성난 트롤보다 뜨겁습니다. 착용은 본인 책임입니다.\\N'),
(50146, '트롤 헤어 염색약: 노란색', '트롤과 정령이 서로 차지하려 싸울 만큼 반짝입니다. 저주는 환불 대상이 아닙니다.\\N'),
(50147, '트롤 헤어 염색약: 풀색', '정글처럼 푸릅니다. 뱀, 벌레, 그리고 나쁜 선택으로 가득하죠.\\N'),
(50148, '트롤 헤어 염색약: 민트 블루', '물처럼 시원하고, 그 아래 숨어 있는 생물처럼 날카롭습니다.\\N'),
(50149, '트롤 헤어 염색약: 연한 파란색', '파도처럼 시원하지만 한 번 잘못 움직이면 로아의 먹잇감이 될 겁니다.\\N'),
(50150, '트롤 헤어 염색약: 진한 파란색', '바다 깊은 곳처럼 어둡습니다. 아래에 뭐가 있는지는 묻지 마세요.\\N'),
(50151, '트롤 헤어 염색약: 애쉬 그레이', '부두술을 잘못 건드린 트롤의 영혼처럼 회색입니다. 착용은 본인 책임입니다.\\N'),
(50152, '트롤 헤어 염색약: 백설 공주', '눈처럼 희고, 담요를 훔쳐 갈 트롤처럼 차갑습니다.\\N'),
(50153, '오크족 헤어 염료: 청흑색', '선술집에서 또 한바탕 싸운 뒤 멍든 얼굴처럼 검푸릅니다.\\N'),
(50154, '오크족 헤어 염료: 오크 브라운', '전쟁노래 협곡의 나무처럼 갈색이고 튼튼합니다. 우리처럼 강합니다. 어쩌면 우리보다 더요.\\N'),
(50155, '오크족 헤어 염료: 진한 보라색', '세상의 종말을 외치는 음침한 이교도들의 로브처럼 짙은 산딸기빛 적자색입니다. 또 시작이군요.\\N'),
(50156, '오크족 헤어 염색약: 라일락 바이올렛', '트롤의 깃발처럼 깊고 따뜻한 보라색입니다. 아름답지만 언제든 싸울 준비가 되어 있습니다.\\N'),
(50157, '오크족 헤어 염료: 진한 보라색', '그 계약서에 서명한 뒤의 영혼처럼 차갑고 짙은 보랏빛입니다. 악도 이렇게 멋질 수 있군요.\\N'),
(50158, '오크족 헤어 염료: 검정색', '검은바위처럼 어둡고 사촌의 머리통보다 단단합니다. 쓰든가, 입 다무세요.\\N'),
(50159, '오크족 헤어 염색약: 다크 애쉬 그레이', '전쟁이 지나간 땅처럼 회색입니다. 감당 못 하겠다면 동굴로 돌아가세요.\\N'),
(50160, '오크족 헤어 염색약: 라이트 애쉬 그레이', '드레노어의 마지막 잔해처럼 창백하고 먼지투성이입니다. 남은 게 이것뿐이니 자랑스럽게 걸치세요.\\N'),
(50161, '언데드 헤어 염색약: 라임 그린', '당신의 영혼, 아니 영혼이 없다는 사실처럼 흐릿하고 유령 같은 녹색입니다.\\N'),
(50162, '언데드 헤어 염색약: 애쉬 로즈', '무덤 위 장미의 입맞춤처럼 생기 잃은 적자색입니다.\\N'),
(50163, '언데드 헤어 염색약: 머드 브라운', '우리를 삼킨 역병처럼 갈색입니다. 우리가 죽음을 받아들였듯 이 색도 받아들이세요.\\N'),
(50164, '언데드 헤어 염색약: 그린 블론드', '금발이라 부를 수 있다면 말이죠. 어둡고 음산합니다. 우리의 머리카락과 삶처럼요.\\N'),
(50165, '언데드 헤어 염색약: 애쉬 블론드', '금발이지만 좀 더 잿빛입니다. 무덤에 너무 오래 누워 있던 피부처럼요.\\N'),
(50166, '언데드 헤어 염색약: 민트 블루', '피처럼 푸르고, 차갑고, 죽어 있습니다. 포세이큰에게 완벽한 색입니다.\\N'),
(50167, '언데드 헤어 염색약: 머드 그린', '짙은 녹색입니다. 왕립 연금술 학회에서 요즘 가장 인기라네요.\\N'),
(50168, '언데드 헤어 염색약: 라이트 애쉬 그레이', '청록색이지만 죽은 빛입니다. 우리가 떠도는 땅처럼요.\\N'),
(50169, '언데드 헤어 염색약: 라이트 틸', '보라색이지만 썩은 빛입니다. 이 색을 만드는 데 시체 부위는 사용하지 않았습니다.\\N'),
(50170, '언데드 헤어 염색약: 더티 퍼플', '우리의 심장처럼 검고, 우리가 물려받은 세상처럼 썩어 있습니다.\\N'),
(50189, '권위의 고리', '카라잔의 문장이 새겨져 있다.'),
(50200, '다크문 톤크', '아제로스 전역의 어린이들이 가장 좋아하는 이 작고 튼튼한 장난감은 아무리 활발한 상상력이라도 견뎌낼 수 있습니다.'),
(50201, '유효기간이 지난 겨울 베일 파티 초대장', '2019년 새해 복 많이 받으세요!'),
(50202, '터틀루의 알', '이 불쌍한 거북이는 좀 타락했지만, 마음씨는 여전히 사랑스러워요.'),
(50203, '오염된 모래', '이 모래는 시간 여행에 연루된 타락한 생명체들을 덮고 있습니다. 만약 당신이 시간의 동굴 안에서 누군가를 찾을 수 있다면, 이 모래는 다시 정화될 수 있을 것입니다.'),
(50204, '와일드해머 I [드워프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50205, '암흑철 [드워프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50206, '지구인 [드워프, 남성만 해당]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50207, '검은바위 I [오크]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50208, '혼돈 [오크]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
