INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(50224, '드레드스컬 III [오크, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50225, '숲 II [트롤]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50230, '에를가딘의 생존 가이드', '장애물을 극복하고 야생을 길들이는 데 필요한 도구를 만드는 방법을 가르치며, 최대 숙련도 150까지 도달할 수 있도록 도와줍니다.'),
(50231, '튼튼한 로프', '튼튼하게 엮은 가죽 밧줄.'),
(50232, '저렴한 고블린 오일', '냄새가 끔찍해.'),
(50233, '나무 곤봉', '나무로 만든 단순한 막대기.'),
(50234, '개요: 여행자용 텐트', '난쟁이 인형 베개는 포함되어 있지 않습니다.'),
(50235, '개요: 어선', '보트 초보자를 위한 안내서, 제2판.'),
(50236, '스톰본의 망토', '우리는 용과 용기수 사이의 유대감을 완전히 이해한다고 주장하지는 않겠습니다. 현명한 이들이 수 세기 동안 그 신비를 고심해 왔으니까요. 하지만 우리는 용이 말이 아니라는 것, 즉 아무나 안장을 얹는다고 해서 탈 수 있는 존재가 아니라는 것을 알고 있습니다.'),
(50243, '폼파의 긁는 막대기', '이런 걸로 긁는 사람은 미친 사람이나 할 짓이다.'),
(50250, '와일드해머 II [드워프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50251, '와일드해머 3세 [드워프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50252, '와일드해머 IV [드워프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50290, '아조타 [인간, 여성만 해당]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50291, '지옥 [인간, 남성만 해당]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50292, '신비로운 [인간]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(50357, '나이트워치의 흉갑', '밤을 지키며 그림자에 한시도 방심하지 않는 이들을 위해 만들어졌습니다.\\N'),
(50358, '나이트워치의 벨트', '밤을 지키며 그림자에 한시도 방심하지 않는 이들을 위해 만들어졌습니다.\\N'),
(50359, '나이트워치의 바지', '밤을 지키며 그림자에 한시도 방심하지 않는 이들을 위해 만들어졌습니다.\\N'),
(50360, '나이트워치의 부츠', '밤을 지키며 그림자에 한시도 방심하지 않는 이들을 위해 만들어졌습니다.\\N'),
(50361, '나이트워치의 장갑', '밤을 지키며 그림자에 한시도 방심하지 않는 이들을 위해 만들어졌습니다.\\N'),
(50376, '힐스브래드 타바드', '힐스브래드에서 벌어진 전투를 기억하게 합니다.\\N'),
(50399, '고대 퀘르도레이 말', '이 말은 한때 영원의 샘 기슭에서 풀을 뜯던 훌륭한 말들의 혈통을 이어받았습니다.'),
(50400, '제브라를 타고', '제브라는 고집이 세고 물어뜯는 습성 때문에 아제로스에서 탈것으로 거의 사용되지 않습니다.'),
(50401, '갑옷상아랩터', '오랜 기간 트롤의 동맹이었던 이 정글 사냥꾼들은 주인과 특별한 유대감을 형성합니다. 그들은 주인의 탈것이자 수호자, 그리고 친구가 됩니다.'),
(50402, '갑옷을 입은 보라색 랩터', '오랜 기간 트롤의 동맹이었던 이 정글 사냥꾼들은 주인과 특별한 유대감을 형성합니다. 그들은 주인의 탈것이자 수호자, 그리고 친구가 됩니다.'),
(50403, '장갑 붉은 랩터', '오랜 기간 트롤의 동맹이었던 이 정글 사냥꾼들은 주인과 특별한 유대감을 형성합니다. 그들은 주인의 탈것이자 수호자, 그리고 친구가 됩니다.'),
(50404, '갑옷을 입은 흑요석 랩터', '오랜 기간 트롤의 동맹이었던 이 정글 사냥꾼들은 주인과 특별한 유대감을 형성합니다. 그들은 주인의 탈것이자 수호자, 그리고 친구가 됩니다.'),
(50406, '섀도혼 사슴', '강렬하고 아름다운 존재.'),
(50407, '나이트메어 드림러너', '단단한 강철과 복수심에 불타는 영혼으로 이루어진 악몽 같은 이 동반자는 아무런 불평 없이 당신을 용암의 심장부까지 따라갔다가 돌아올 것입니다.'),
(50408, '환상: 드리아드', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50426, '황무지 얼룩말', '줄무늬가 있어요!'),
(50435, '일루전: 드레드로드', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50436, '일루전: 스몰더쏜 버서커', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50437, '일루전: 나가 익스플로러', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50438, '환상: 나가 사이렌', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50439, '환상: 하피', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(50440, '금이 간 붉은십자군 휘장', '한때 굽히지 않는 열정의 상징이었습니다. 지금은 산산이 부서졌지만 붉은십자군의 광신적인 헌신의 흔적은 여전히 남아 있습니다.\\N'),
(50520, '피로의 문양', '이 문양은 휴식 경험치를 얻는 것을 막아주지만, 무기 숙련도 상승폭은 두 배가 됩니다.'),
(50524, '그놈 자동차 키', '이 기능을 사용하면 놀라운 노움 발명품을 조종할 수 있습니다. 조심해서 다루세요.'),
(50525, '고블린 자동차 키', '꼬마야, 넌 지금 최고의 고블린 자동차를 몰고 있구나! 뭐가 그렇게 빠른 거지? 당연히 폭발이지!'),
(50535, '놀드랏실 수사슴', '고대 노르드라실의 힘이 깃든 위풍당당한 이 말은, 그 발굽에 자연의 힘이 메아리처럼 울려 퍼진다.'),
(50536, '어스름', '어둠과 아름다움의 완벽한 균형을 구현하는 산.'),
(50545, '이세라의 보석', '이세라의 힘이 그 안에 흐르고 있다...'),
(50600, '소환: 이발사', '순식간에 스타일을 바꾸고 싶을 때, 나만의 개인 이발사 스닙팁을 불러오세요.'),
(50601, '소환: 외과의사', '개인 전담 외과의사, 닥터 탑노스를 불러보세요. 흉터 제거, 코뼈 골절 교정 등 다양한 시술을 제공합니다.'),
(50602, '소환: 경매인', '동네 고블린 사업가를 불러내세요. 사고팔고 입찰하세요. 어디에서도 찾아볼 수 없는 최고의 거래를 찾을 수 있을 거예요!'),
(50603, '인종 변경 토큰: 인간', '마우스 오른쪽 버튼을 클릭하여 사용하세요.'),
(50604, '종족 변경 토큰: 노움', '마우스 오른쪽 버튼을 클릭하여 사용하세요.'),
(50605, '종족 변경 토큰: 드워프', '마우스 오른쪽 버튼을 클릭하여 사용하세요.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

