(50613, '종족 변경 토큰: 고블린', '마우스 오른쪽 버튼을 클릭하여 사용하세요.'),
(50745, '자기 절제의 문양', '이 문양은 도박을 금지합니다.'),
(50746, '불명예의 문양', '저는 PvP를 재미로 해요! 이 문양은 명예 점수를 얻는 것을 막습니다.'),
(51002, '그린 스팀 통크', '아제로스 전역의 어린이들이 가장 좋아하는 이 작고 튼튼한 장난감은 아무리 활발한 상상력이라도 견뎌낼 수 있습니다.'),
(51003, '퍼플 스팀 통크', '증기선을 소환하고 조종하세요.'),
(51004, '고블린 경품 상자', '경품 추첨에 참여하세요!'),
(51005, '그놈 경품 상자', '경품 추첨에 참여하세요!'),
(51007, '텔드라실 새싹', '정말 행복해 보이는 작은 나무네요!'),
(51009, '데이지의 선물 상자', '놀라울 정도로 정성스럽게 포장되었네요.'),
(51010, '어둠 [트롤]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(51011, '얼음 [트롤]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(51020, '딸기 슈냅스', '파티는 선물을 의미하죠! 그리고 파티는 즐거움으로 가득 차 있어요. 슈냅스가 없으면 즐거움이 무슨 의미가 있겠어요?'),
(51021, '스피디의 주크박스', '아무도 보지 않는 것처럼 춤춰라.'),
(51022, '정성껏 쓴 생일 카드', '미래에 다시 한번 이야기 나눠보죠. 다음번엔 아주 먼 미래에 만날 수 있을 겁니다. 아나크로노스 드림.'),
(51024, '저주받은 우상', '부패의 힘으로 가득 차 있다.'),
(51029, '방랑자의 문양', '품질이 낮거나 보통인 아이템만 장착할 수 있습니다.'),
(51043, '보이드 링크드 사첼', '이 가방에 어떻게 그렇게 많은 물건이 들어가는지는 말하지 않는 게 좋겠다.'),
(51050, 'S.W.A.G 고글', '저는 밤에 고글을 착용합니다.'),
(51055, '참나무의 문양', '이 문양을 사용하여 생명의 나무로 변신하세요.'),
(51056, '사슴의 문양', '이동 변신 상태가 활성화되면 숲 사슴의 모습을 하게 됩니다.'),
(51057, '서리검의 문양', '고양이 변신이 활성화되면 서리검의 모습을 띨 것입니다.'),
(51058, '이상한 눈덩이', '무슨 이유인지 모르겠지만 노란색이네요.'),
(51060, '겨울맞이 선물 상자', '뭘 기다리고 있어? 지금 바로 열어봐!'),
(51064, '흰 수사슴의 문양', '활성화하면 여행 변신이 흰 사슴의 모습으로 바뀝니다.'),
(51065, '환상: 그림자', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51066, '일루전: 플레임웨이커', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51067, '환상: 뼈뱀', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51070, '비전 나무정령의 문양', '활성화하면 나무 변신이 비전 나무정령의 모습으로 바뀝니다.'),
(51200, '환상: 고블린', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51201, '환상: 워겐', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51203, '환상: 하이 엘프', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51205, '환상: 유령', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51206, '환상: 밴시', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51207, '환상: 뱀의 군주', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51208, '환상: 서큐버스', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51209, '환상: 쥐', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51210, '환상: 녹색 용족', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51215, '환상: 사티로스', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51220, '잃어버린 농장 양', '무리에서 길을 잃은 친근한 농장 양이 이제 당신을 충실히 따라다니며 당신의 모험 속에서 든든한 존재가 되어줍니다.'),
(51221, '룰루', '사랑스러운 아기 양들.'),
(51230, '거북이의 문양', '죽으면 경험치의 5%를 잃고, 몬스터를 처치하면 경험치의 절반을 얻습니다.'),
(51240, '드래곤 슬레이어 마스터의 셔츠', '오닉시아를 물리친 우리의 용감한 영웅들에게 경의를 표합니다.'),
(51245, '토르타의 부두 인형', '바늘이 포함되어 있습니다.'),
(51246, '사라 새드휘슬의 의류', '이 검은색 웨딩드레스 정말 아름다워요!')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51247, '크로미의 여덟 번째 예비 회중시계', '단 한 번이라도, 누군가가 나에게 난쟁이나 시간 여행에 대한 바보 같은 농담 없이 인사해줬으면 좋겠어.'),
(51249, '스노볼', '새해 복 많이 받으세요!'),
(51250, '작은 겨울맞이 나무', '풍성한 가지와 아름답고 밝은 불빛으로 가득한 겨울맞이 축제 트리를 소환하세요!'),
(51251, '헤드윅', '즐거운 겨울맞이 축제 보내세요!'),
(51252, '브론즈 드레이크', '잃어버린 시간은 결코 되찾을 수 없다.'),
(51253, '환상: 푸르볼그', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(51255, '장난감 기차 세트', '모두 탑승하세요!'),
(51257, '사랑스러운 하트 모양 상자', '원래는 초콜릿 보관용으로 설계되었습니다.'),
(51258, '크고 예쁜 수제 가방', '당신의 마음만큼이나 커요.'),
(51259, '리틀 포니', '발렌타인데이에 입양되었습니다.'),
(51260, '헤르만 2세 왕자', '사랑하는 우리 고양이, 장난꾸러기를 추모하며.'),
(51261, '작은 소', '발렌타인데이에 입양되었습니다.'),
(51264, '블래스트 쉴드', '폭발로부터 사용자를 보호합니다. 단, 특정 조건이 적용될 수 있습니다.'),
(51266, '얼음곰의 문양', '곰 변신이 활성화되면 얼음곰의 모습을 하게 됩니다.'),
(51267, '매콤한 소고기 부리토', '일명 \'피자 병\'이라고도 불린다고 합니다.'),
(51270, '성서: 신성한 일격 II', '신성 공격(2단계)을 가르칩니다.'),
(51271, '성서: 신성한 일격 III', '신성 공격(3단계)을 가르칩니다.'),
(51272, '성서: 신성한 일격 IV', '신성 공격(4단계)을 가르칩니다.'),
(51273, '성서: 신성한 일격 V', '신성 공격(5단계)을 가르칩니다.'),
(51274, '성서: 신성한 일격 VI', '신성 공격(6단계)을 가르칩니다.'),
(51275, '성서: 신성한 일격 VII', '신성 공격(7단계)을 가르칩니다.'),
(51276, '성서: 신성한 일격 VIII', '신성 공격(8등급)을 가르칩니다.'),
(51305, '작은 패션 동전 파우치', '패션 코인 5개가 들어 있습니다.'),
(51306, '패션 동전 대용량 파우치', '패션 코인 10개가 들어 있습니다.'),
(51310, '고장난 휴대용 웜홀 생성기', '기술적으로 매우 진보된 에너지-물질 혼합기.'),
(51312, '휴대용 웜홀 생성기: 스톰윈드', '첨단 기술이 적용된 에너지-물질 혼합기. 동전을 넣어 계속 진행하세요!'),
(51313, '휴대용 웜홀 생성기: 오그리마', '첨단 기술이 적용된 에너지-물질 혼합기. 동전을 넣어 계속 진행하세요!'),
(51325, '엘윈 호박', '통통하네요. 파이로 만들기에 딱 좋아요.'),
(51330, '맛있는 호박 파이', '만져보면 부드럽다.'),
(51332, '스톤필드 할머니의 등불', '숲 속에서 길을 잃지 않을 만큼 밝습니다.'),
(51356, '카라잔 암호 열쇠', '녹이 슬었다.'),
(51360, '에메랄드 곰의 문양', '곰 변신이 활성화되면 에메랄드 곰의 모습을 하게 됩니다.'),
(51361, '꿈의 종족의 문양', '달빛사자 변신이 활성화되면 꿈의사자 모습으로 변합니다.'),
(51362, '꿈 표범의 문양', '고양이 변신이 활성화되면 꿈의 표범의 모습을 띨 것입니다.'),
(51421, '카라반 코도', '당신의 온갖 소지품을 싣고 어디든 함께합니다.'),
(51425, '테레사의 구리 동전', '저는 운이 별로 없네요. 이 동전을 분수에 던져주시겠어요?'),
(51431, '서리피족의 문양', '달빛족 변신이 활성화되면 서리족의 모습을 하게 됩니다.'),
(51432, '별의 문양', '활성화된 동안, 당신의 달빛족 변신 형태는 천체 변신 형태를 띠게 됩니다.'),
(51433, '리틀 폰', '그녀는 친구들과 어울리는 것을 좋아합니다. 정확히 말하면 75명이나 되죠.'),
(51600, '고대 마법 로켓', '오래된 주문이 여전히 신비로운 룬 문자와 함께 맴돌고 있지만, 주문은 너무 닳아서 제대로 읽을 수 없다.'),
(51601, '오트마르 가리토스의 동전', '소원은 당신 혼자 간직하세요. 저는 분수와는 협상하지 않습니다.'),
(51602, '나타노스 마리스의 동전', '그건 오로지 그녀의 믿음 덕분이었어. 할두론이나 렌타르, 그 변덕스러운 로르테마르 때문이 아니었지. 오직 그녀뿐이었어.'),
(51603, '아르타스의 금화', '벌써부터 내 꿈속에는 왕국, 다스릴 땅이 자리 잡고 있어. 뭘 바라겠어? 얼린 스콘 하나면 되겠지...'),
(51604, '스피디의 금화', '친구들도 꼭 데려오세요.'),
(51605, '베다스의 은화', '이제 습격대 전체가 내 구멍을 이용할 수 있게 됐어!'),
(51606, '펠리시아의 은화', '스타일은 말하지 않고도 자신이 누구인지를 표현하는 방식입니다.'),
(51607, '신렉의 은화', '남들이 사는 대로 살게 하거나, 그렇게 하다가 죽거나.'),
(51608, '므르글-므르글 왕의 동전', '가끔은 멀록들이 내가 그들을 위해 해주는 모든 일에 감사하지 않는 것 같다는 생각이 들어요.'),
(51609, '바르틸라스의 구리 동전', '패트리샤가 항상 내 곁에 있었으면 좋겠어!'),
(51610, '머키의 동전', '므르 글르르글 므르 글르르글 글르르.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51611, '에이트리그의 구리 동전', '무슨 일이 닥치든, 호드는 살아남을 것이다. 반드시 그래야만 한다!'),
(51612, '농부의 은화', '난 정말 건망증이 심해! 기억력이 좀 더 좋았으면 좋겠어. 잠깐, 나 여기 안에 동전 하나 던지지 않았나?'),
(51613, '크릴의 구리 동전', '쾅! 지금 쾅? 쾅 하는 소리가 났으면 좋겠어. 쾅! 이 동전이 부서진 것 같아. 폭발할까?'),
(51614, '메디브의 은화', '결말은 알고 있어요… 다만 이 부담을 조금이라도 덜 수 있는 방법을 알았으면 좋겠어요.'),
(51615, '무라딘 청동수염의 은화', '성령께서 얼어붙은 북극으로 향하는 우리의 탐험을 보호해 주시기를 바랍니다.'),
(51616, '판드랄 스태그헬름의 은화', '모래사막의 전쟁... 그 일이 아예 없었던 것처럼 잊을 수 있다면 얼마나 좋을까.'),
(51617, '티란데의 동전', '제가 소중히 여기는 사람들을 보호하고, 엘룬의 은총과 빛을 계속해서 비추기 위해서입니다.'),
(51618, '말퓨리온의 동전', '우리는 이 악몽을 막기엔 너무 늦었던 걸까요?'),
(51619, '우서 라이트브링어의 금화', '젊은 아서스는 자신의 힘을 다스리기 위해 인내심을 배워야 합니다. 언젠가 그가 힘이 아닌 배려로 이끄는 법을 배우기를 기도합니다.'),
(51620, '안두인 워린의 금화', '나도 빨리 어른이 됐으면 좋겠어. 마치 몇 년째 10살인 것 같아.'),
(51621, '티리온 포드링의 금화', '사랑하는 태란이가 자신이 아끼는 사람들을 지킬 수 있을 만큼 강해지기를 바랍니다.'),
(51622, '알론수스 파올의 구리 동전', '언젠가는 빛의 길을 일반 대중에게 전파하고 삼덕의 가치를 가르치고 싶습니다.'),
(51623, '안토니다스의 은화', '제가 바꿀 수 없는 것을 받아들일 수 있는 힘과 바꿀 수 있는 것을 바꿀 수 있는 용기, 그리고 그 차이를 분별할 수 있는 지혜를 주소서.'),
(51624, '여군주 카트라나 프레스터의 금화', '잘 들어봐, 작은 소원 샘물아. 네가 뭘 원하는지 안다면, 네 모든 힘을 내게 줘야 할 거야.'),
(51625, '칼리아 메네틸 공주의 구리 동전', '잘생긴 귀족 프레스토 경께서 저를 알아봐 주셨으면 좋겠어요! 정말 멋지세요!'),
(51626, '마커스 조너선 이등병의 구리 동전', '나도 언젠가 멋지고 풍성한 콧수염을 기르고 싶어.'),
(51627, '에르의 동전', '음경.'),
(51628, '토르타의 금화', '왼쪽 대륙이 파괴되었다면 오른쪽 대륙에서 플레이하세요.'),
(51629, '아우렐리아누스의 은화', '리치의 힘… 아니, 빛의 힘으로, 불타올라라!'),
(51630, '기프티드의 은화', '특정 성기사가 드디어 치유하는 법을 배우길 바라…'),
(51631, '스멀트론의 은화', '난 최고야.'),
(51632, '모모의 은화', '프로스트볼트로 공격해!'),
(51633, '클로의 은화', '촘퍼의 치료를 우선시할 수 있을까요?'),
(51634, '마르타의 은화', '러쉬 비!'),
(51635, '폼파의 고무 오리', '돌팔이 의사!'),
(51636, '촘퍼의 잃어버린 이빨', '그거 크네요.'),
(51637, '풍선형 썬더퓨리, 윈드시커의 축복받은 검', '바람이 빠졌다.'),
(51638, '란 왕의 은화', '가로나, 이 골칫거리가 끝나면 우리는 분명 좋은 결과를 보고 함께 웃을 수 있을 거야. 내 말을 믿어!'),
(51639, '스멀트론의 선글라스', '저는 밤에 고글을 착용합니다!'),
(51640, '엔지의 동전', '5분 안에 공포를 느껴보세요!'),
(51641, '모모의 동전', '조심해! 조심해! 조심해!'),
(51642, '헤르체그의 은화', '원소의 지배자, 폭풍의 황제, 양의 파괴자, 그리고 나머지 공격대원들.'),
(51643, '마르타의 은화', '퍼볼그족을 모두 죽여라.'),
(51644, '카즈그림의 은화', '나는 진정한 전쟁 지도자가 되고 싶다.'),
(51645, '드라구노비의 은화', '아마 당신은 제가 만든 옷을 입고 있을 거예요.'),
(51646, '스카디의 금화', '구루바시 경기장에서 쥐들과 함께 보냈던 그 고요한 밤들을 추억으로 간직하고 싶습니다.'),
(51660, '게오르의 은화', '여전히 매력적인 고스족 여자친구를 찾고 있어요.'),
(51700, '깨진 랩터 알', '곧 부화할 것 같아! 안에는 무엇이 있을까?'),
(51702, '불타는 날개의 문양', '불타는 날개를 달고 치유사로서의 실력을 뽐내세요.'),
(51705, '심플한 나무 화분', '특별히 수작업으로 제작된 화분에 비옥하고 물을 충분히 준 흙이 담겨 있습니다.'),
(51706, '컨트리 호박씨', '간단한 나무 화분에 심을 수 있습니다. 물과 비료를 주어야 합니다.'),
(51707, '산딸기 덤불 씨앗', '내륙 지방에서 자라는 다채로운 색깔의 열매입니다. 간단한 나무 화분에 심을 수 있으며, 물과 비료를 주어야 합니다.'),
(51708, '줄무늬 멜론 씨앗', '세상에서 가장 달콤한 품종! 심플한 나무 화분에 심을 수 있습니다. 물과 비료를 줘야 합니다.'),
(51709, '농부를 위한 안내서: 땅에서 살아남기!', '역대 최고의 품종을 선택하고 재배하는 방법!'),
(51710, '통통한 시골 호박', '호박은 생각보다 훨씬 무겁습니다.'),
(51711, '스위트 마운틴 베리', '이 작고 평범해 보이는 열매에는 엄청난 효능이 숨겨져 있습니다!'),
(51712, '즙이 많은 줄무늬 멜론', '너무 달콤하고 즙이 많아요!'),
(51713, '통통한 시골 호박', '호박은 생각보다 훨씬 무겁습니다.'),
(51714, '스위트 마운틴 베리', '이 작고 평범해 보이는 열매에는 엄청난 효능이 숨겨져 있습니다!'),
(51715, '고블린 세뇌 장치', '사용에 따른 책임은 사용자에게 있습니다. 재능 재설정 절차에는 비용이 발생합니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51716, '마법 버섯 포자', '맛있고 환각 성분은 전혀 없습니다.'),
(51717, '딱딱한 버섯', '맛있고 환각 성분은 전혀 없습니다.'),
(51718, '즙이 많은 줄무늬 멜론', '너무 달콤하고 즙이 많아요!'),
(51720, '파워 머쉬룸', '맛있고 환각 성분은 전혀 없습니다.'),
(51725, '실키 웨빙', '언데드 네루비안 감독관이 엮어낸 끔찍한 거미줄. 아르젠트 던의 누군가가 관심을 가질지도 몰라.'),
(51739, '작은 거미줄 공', '움직이고 있어요!'),
(51743, '잃어버린 템플러의 유물', '그는 끔찍한 운명을 맞이했다.'),
(51750, '트렙스 타코', '트렙, 생일 축하해!'),
(51754, '자석 칼날', '내면의 힘이 해방되기를 간절히 바라고 있다.'),
(51755, '와일드해머 클랜의 룬', '안에서 천둥소리가 들린다.'),
(51758, '공성 골렘 코어', '불안정해 보입니다.'),
(51759, '시즈 폭격기', '총열 하부 폭탄 발사기가 함께 제공됩니다.'),
(51779, '낡은 무덤의 거대한 도끼', '카라잔에서 가져온 돌 조각으로 만들어진 이 물건에는 여전히 잠재된 마법이 깃들어 있다.'),
(51784, '고대 권력의 벨트', '메디브의 수많은 실험 중 하나.'),
(51792, '이세계의 로브', '이 옷에는 전에 본 적 없는 룬 문자가 새겨져 있습니다. 직조 방식은 마치 다른 세계에서 온 것 같습니다.'),
(51793, '이계의 칼', '이 수정 같은 칼날은 에너지로 맥동하고 있어, 당신은 전에 이런 것을 본 적이 없을 겁니다.'),
(51796, '소멸하는 어둠의 방패', '녹색 룬 문자가 표면을 따라 새겨져 있다.'),
(51807, '그레첸의 슬리퍼', '낡고 편안한 슬리퍼 한 켤레.'),
(51808, '실험용 휴대용 웜홀 생성기', '실험용 모델 X45-OZ. 5초 동안 매우 강력한 방사능을 띤 웜홀을 생성합니다.'),
(51830, '범고래의 문양', '수중 변신이 활성화되면 범고래의 모습을 띨 것입니다.'),
(51831, '유령 늑대의 문양', '유령 형태로 변신하면 유령 늑대의 모습을 하게 됩니다.'),
(51832, '나트레짐 웨지', '어둠이 칼날을 감싼다.'),
(51833, '대퇴골 지팡이', '"전설적인 품질."'),
(51834, '붉은십자군 기둥', '수도원에서 나온 유물.'),
(51835, '스피디 에너지 드링크', '늦은 밤까지 놀고 난 후 힘든 아침에 기운을 북돋아 줄 완벽한 음료입니다.'),
(51836, '환상: 멀록', '물고기 그 이상, 인간 그 이상.'),
(51837, '신디케이트 부적', '이는 당신이 조직에 충성을 맹세한다는 것을 의미합니다.'),
(51840, '풍선 여자', '스멀트론, 생일 축하해!'),
(51841, '토끼발', '새로운 시작을 응원합니다!'),
(51844, '놀라운 석궁', '활시위를 당기고, 조준하고, 쏴라!'),
(51845, '카야의 탄약', '계약된 물품은 오그리마에 정해진 시간에 도착해야 합니다.'),
(51846, '레즐락의 배송', '계약된 물품은 오그리마에 정해진 시간에 도착해야 합니다.'),
(51848, '고대 엘프 로브', '마법을 무분별하게 사용하던 시대의 유물이다.'),
(51849, '썬더혼', '천둥 도마뱀의 힘이 깃들어 있다.'),
(51855, '더럽고 낡은 반지', '너무 가벼워서 손에서 미끄러질 뻔했어요.'),
(51856, '금반지', '순금이라니! 놀랍네요!'),
(51857, '검은바위의 군주 셔츠', '지금 누가 주님이냐!?'),
(51858, '티리스팔 박쥐', '이 불길한 생물은 동부 역병지대의 밤하늘을 배회하며 썩은 고기를 먹고 산다.'),
(51861, '비전의 물', '썬더 블러프의 환영의 웅덩이에서 가져온 성스러운 물이 담긴 작은 병.'),
(51862, '브레이브의 소총', '슈할로 전사들은 햇빛이 반사되는 모습 때문에 이 총을 "그린보이"라고 부릅니다.'),
(51889, '하이잘 곰 새끼', '꿈틀거리는 새끼곰은 나무에서 내려오려 하지 않았습니다. 결국 우리는 나무 꼭대기에서 새끼곰을 던져야 했습니다.'),
(51890, '모험가의 셔츠', '2020년 Turtle WoW 오픈 하우스 행사에서 받은 선물입니다.'),
(51891, '신비로운 점쟁이', '매우 신뢰할 수 있는 사람입니다.'),
(51894, '무료 티셔츠', '2021년 Turtle WoW 오픈 하우스 행사에서 받은 선물입니다. 꼬리표에는 "진흙톱니 거점에서 제작"이라고 적혀 있습니다.'),
(51898, '용감한 여행자 셔츠', '2021년 12월 1일 — 내가 크툰을 겁줘서 심장마비까지 일으키게 만들었는데, 얻은 건 이 형편없는 티셔츠뿐이잖아!'),
(51899, '프로스트위브 셔츠 오브 프로스트 소울즈', '2021년 10월 4일 — 켈투자드가 처음으로 패배했습니다!'),
(51900, '안퀴라즈의 고갈된 돌', '그 돌은 이제 아무런 힘도 없다. 그저 풍뎅이 벽에서 일어났던 사건들을 상기시키는 기념물일 뿐이다.'),
(51901, '스카라브 군주의 의복', '10시간 동안 벌레를 밟아 죽였는데, 얻은 거라고는 이 형편없는 셔츠뿐이야.'),
(51904, '끊임없이 떨어지는 음식 부스러기로 너덜너덜해진 튜닉', 'Turtle WoW를 자신들의 플레이 환경으로 선택해 주신 플레이어 여러분께 드리는 희귀한 유물입니다!'),
(51920, '어둠의 손길 [언데드]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51921, '블러드 위도우 [언데드]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(53000, '봉인된 편지', '인장에는 문장이 없습니다.'),
(53005, '붉은십자군 휘장', '이 휘장은 착용자가 스칼렛 크루세이드의 정식 구성원임을 나타냅니다.'),
(53008, '환상: 머리 두 개 달린 오거', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(54000, '푸른개구리', '마음을 편안하게 해주는 울음소리로 유명한 신비로운 양서류로, 그 소리를 듣는 이에게 평온함을 가져다준다고 전해진다.'),
(54001, '꿈개구리', '이 신비로운 존재는 잠든 모험가들의 꿈속으로 들어가 그들에게 지침과 지혜를 제공하는 능력을 지녔다고 믿어집니다.'),
(54002, '황소개구리', '강인한 울음소리를 내는 튼튼한 양서류로, 주로 물가 근처에서 발견되며, 일부 사람들에게는 힘과 회복력의 상징으로 여겨집니다.'),
(54003, '무한 개구리', '시간과 공간의 법칙을 거스르는 듯 차원 사이를 자유자재로 넘나드는 특이한 개구리.'),
(54004, '독개구리', '이 치명적인 양서류의 선명한 색깔에 현혹되지 마세요. 이 생물의 피부는 가장 강력한 적조차 무력화시킬 수 있는 강력한 독소를 분비합니다.'),
(54005, '눈개구리', '아제로스의 혹독한 추위 지역에 서식하는 이 강인한 개구리는 얼음 환경에서 살아남도록 적응했으며, 푸른빛 피부는 눈 덮인 풍경 속에서 몸을 위장하는 데 도움을 줍니다.'),
(54006, '핑크 개구리', '섬세하고 매혹적인 이 희귀한 개구리 종은 선명한 분홍색으로 사람들을 사로잡으며, 이 색깔은 주인에게 행운과 번영을 가져다준다고 믿어집니다.'),
(54007, '황금개구리', '전설에 따르면 이 반짝이는 양서류는 부와 풍요를 예고한다고 합니다.'),
(54008, '연못개구리', '고요한 연못과 습지에서 흔히 볼 수 있는 이 소박한 개구리는 자연의 품속에서 찾을 수 있는 소박한 기쁨을 일깨워줍니다.'),
(55004, '부서진 불타는 칼날 메달', '부서진 메달입니다. 이제는 거대한 악을 물리친 승리의 증표가 되었습니다.'),
(55020, '충실한 고리', '알터랙에 대한 헌신의 상징입니다.'),
(55021, '알베로의 강화된 곤봉', '고통을 조금 더 주려고 금속을 한 겹 더 덧댄 모양입니다.'),
(55022, '비숍 미란다의 로사리', '분명히 사용한 흔적이 있습니다. 뛰어난 신앙심을 지닌 이의 물건이었습니다.'),
(55023, '하스의 스탈알트 방어', '방패 뒤로 몸을 숨겨 10초 동안 받는 피해를 10% 감소시키지만 이동 속도가 80% 감소합니다. (재사용 대기시간 2분)'),
(55024, '알넬라의 실켄 바지', '달라란의 학생들이 흔히 입던 옷입니다.'),
(55026, '알테라키 훈티응 창', '대상에게 창을 던져 75의 피해를 입히고 2초 동안 이동 속도를 30% 감소시킵니다. (재사용 대기시간 2분)'),
(55027, '스느오프이크 이그레', '이 기능에는 소환수 주문을 추가해야 합니다. Torta에게 알려 주세요.'),
(55028, '캅단의 팟이느트 앗치', '언제나 심장을 꿰뚫습니다.'),
(55030, '아리덴의 프레주디케', '알터랙의 보물고에서 나온 검입니다. 마침내 더 나은 주인을 만났군요. 적중 시 일정 확률로 분노가 솟아 15초 동안 공격할 때마다 생명력을 10 회복합니다.'),
(55032, '알테라키 프린켓스의 왕실의 로브', '알터랙의 후계자는 불같은 성격으로 유명합니다. 치유 주문 사용 시 일정 확률로 대상에게 불같은 기질을 불어넣어 10초 동안 공격 속도와 시전 속도를 5% 증가시킵니다.'),
(55034, '그림 바톨 산악경비대 어깨갑옷', '오랫동안 사용되지 않았습니다.'),
(55035, '데레릭트 가문 크란 토템', '희미하게 도끼 문장이 새겨져 있습니다.'),
(55038, '몰락한 영웅들 \'힘날', '위대한 전당의 형제자매들에게.'),
(55040, '스키팔르 어깨보호구', '망토 안에 낙하산이 짜여 있습니다.'),
(55041, '와일드해머 폭풍소환사', '번개가 찌릿찌릿 튑니다.'),
(55056, '스펠르오벤 노비리티 망토', '허영심 많은 명가 천문학자가 걸치던 망토입니다.'),
(55058, '룬 -인스크리벧 판금 다리보호구', '엘프 룬 문자가 표면 위를 빠르게 흘러다닙니다.'),
(55060, '시엔드라랄 장로의 그란드스탑프', '만 년의 지식이 이 지팡이를 타고 흐릅니다.'),
(55063, '프로랄 고리', '<시몬이 즐기던 비교적 덜 치명적인 취미 중 하나입니다.>'),
(55064, '올? 빅긴? 스 숩스티투테 빗자루', '<무엇이든 두루 해내는 만능형입니다.>'),
(55065, '좋은 행운의 스묻게? 스 목걸이', '<표면에서 고양잇과 동물의 실루엣이 어렴풋이 느껴집니다.>'),
(55068, '잔의 레페리피카션 브랏텔', '주문 필요: 사용 효과 - 대상에게 방사능 에너지를 발사해 오염된 노움으로 만들고, 12초 동안 대상이 입히는 피해를 15, 이동 속도를 20% 감소시킵니다. (재사용 대기시간 5분) 실제 문구: <아직도 완전한 시제품입니다. 다른 노움들에게 보여 주지 마세요.>'),
(55069, '도안: 가을 크니벳의 어깨보호구', '주문 필요: 사용 효과 - 낙하하는 칼날의 어깨보호구 제작법을 배웁니다.'),
(55071, '라벤홀드트 까마귀', '주문 필요: 사용 효과 - 이 동료를 소환하는 법을 배웁니다. 실제 문구: <라벤홀트의 요원들은 감시와 연락, 그리고 엄숙한 순간의 말벗으로 이 까마귀들을 이용합니다.>'),
(55073, '미로콧 \'프이로소프이칼 딧셀타션', '주문 필요: 사용 효과 - 책에 몰입해 깨달음의 경지에 들어가 12초에 걸쳐 마나와 생명력을 2100 회복합니다. 집중을 유지하려면 계속 읽어야 합니다. 실제 문구: <끝도 없이 길게 이어지는 문장이 졸음을 부릅니다.>'),
(55074, '도면: 혹한의 우잇펠', '주문 필요: 사용 효과 - \'얼어붙은 속삭임\' 제작법을 배웁니다.'),
(55075, '혹한의 우잇펠', '주문 필요: 착용 효과 - 공격 시 일정 확률로 대상에게 60~75의 냉기 피해를 입힙니다. 실제 문구: <죽음의 얼어붙은 손아귀처럼, 이 단검의 감촉이 희생자가 마지막으로 느끼는 것이 될 것입니다.>'),
(55077, '칼네리아의 노을빛', '<고(故) 조라크 경이 아내에게 준 결혼 선물을 모방한 물건이라는 소문이 있습니다.>'),
(55119, '잊힌 가죽 투구', '이 투구를 만드는 데 사용된 생물은 이미 멸종했을 가능성이 큽니다.'),
(55189, '피 관', '착용 효과: 치명타를 적중시키면 생명력을 12~18 회복합니다.'),
(55190, '장로의 찬란한 관', '착용 효과: 치명타를 받으면 400의 피해를 흡수하는 보호막이 생성됩니다. 발동 확률 100%, 재사용 대기시간 2분.'),
(55208, '줃겓의 목걸이', '그리고 그는 자신의 신념에 따라 심판받게 될 것입니다.'),
(55209, '길 잃은의 메달', '황옥 표면의 균열에는 칼림도어의 태고적 자연이 비칩니다.'),
(55214, '거친 황수정 반지', '모양은 저마다 다르지만 빛나는 모습은 모두 같습니다.'),
(55219, '거친 남옥빛 반지', '셀 수 없이 많은 강물이 모두 대해의 품으로 흘러듭니다.'),
(55224, '운포리시엗 잿불석 반지', '잿불석 반지 안에 깃든 아제로스의 불타는 심장을 받아들이세요. 당신의 열정도 그 못지않게 뜨겁게 타오를 것입니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(55227, '인펠노 잿불석 반지', '착용 효과: 직접 피해를 주는 공격 주문 적중 시 일정 확률로 8초 동안 주문 공격력이 60 증가합니다. (직접 피해 시 10% 확률, 재사용 대기시간 2분)'),
(55230, '피렛톨므 용암 고리', '착용 효과: 자동 공격 시 2% 확률로 대상을 지져 300의 화염 피해를 입힙니다.'),
(55231, '운포리시엗 월장석 반지', '월장석 반지의 매혹적인 빛을 받아들이세요. 반짝임 하나하나에 밤의 비밀이 속삭입니다.'),
(55234, '앗트랄 월장석 고리', '착용 효과: 주문 시전에 성공하면 일정 확률로 시전자에게 마나 50을 회복시킵니다. (60% 확률, 재사용 대기시간 20초)'),
(55237, '수정 크르이르 달 고리', '착용 효과: 자동 공격 시 4% 확률로 주변 공기를 점화해 반경 5미터 내 적에게 120의 피해를 입힙니다.'),
(55275, '눌리피카션의 스리벨스', '한때 강력했던 보석의 파편들이 서로 끌어당기는 듯합니다.'),
(55380, '크랍트스만의 바지', '기름 유출 사고 때문에 이 바지는 상당히 상했습니다.'),
(55387, '인트로둑션 ~로 어둠 알트스', '몇 장이 빠져 있습니다. 설마 그렇게 중요한 내용은 아니겠죠.'),
(55471, '잇탄의 강철 장착무기', '굳센 주먹과 단단한 자세, 필요한 것은 그것뿐입니다.'),
(55504, '아베쿳텔의 닻', '댈린 프라우드무어의 기함에 달려 있던 닻입니다. 이제 심연의 집게발의 정수가 스며들었습니다.'),
(55505, '엘룬의 낫', '이 유물에는 세계와 세계 사이의 장막이 숨겨져 있습니다. 보르겐도르의 어두운 기운은 지금은 잠잠합니다.'),
(55512, '잊힌 가죽 어깨갑옷', '드레노어의 파괴로 많은 종들이 삶의 터전을 잃고 떠돌게 되었습니다.'),
(56062, '지휘의 검은날개 인장', '용들을 지배했다는 증표입니다.'),
(59990, '초라한 편지', '약간 찢어지고 더러운 편지.'),
(59997, '드워프 문자', '이 페이지들은 당신에게 아무런 의미가 없으며, 글자가 있긴 하지만 해독할 수 없을 것처럼 보입니다.'),
(60098, '하이퍼텍 배터리 팩', '최신 기술 발명품에 필요한 전력을 공급합니다. 무제한 전력!'),
(60099, '배터리 구동식 군중 압도기', '건전지는 포함되어 있지 않습니다.\\N'),
(60100, '가족 로켓', '오래된 가문의 문장이 새겨진 목걸이'),
(60101, '봉인된 두루마리', '하이 익스플로러를 위한 극비 정보.'),
(60102, '울둠의 판', '당신이 그 접시를 쥐고 있으면 접시에서 강력한 에너지가 뿜어져 나옵니다.'),
(60103, '울둠의 두 번째 판', '당신이 그 접시를 쥐고 있으면 접시에서 강력한 에너지가 뿜어져 나옵니다.'),
(60104, '늑대 토템', '낡고 상처투성이지만, 그 토템은 여전히 ​​에너지로 가득 차 있다.'),
(60105, '새겨진 멧돼지 가죽', '로그라쉬의 메시지가 새겨진 멧돼지 가죽'),
(60126, '돌의 인장', '외국 문자로 새겨져 있음'),
(60127, '산브 참', '활기 넘치는 윙윙거림'),
(60128, '가렉사의 뿔', '이국적이고, 다른 세상에서 온 뿔피리'),
(60129, '드레닉 헌터 반지', '외국 표식이 있습니다'),
(60131, '아카샤의 홀', '오래전에 잊혀진 신전의 홀'),
(60132, '카르눔의 부적', '오래전 세상을 떠난 현자의 고대 부적'),
(60136, '전리품', '많은 양의 재물과 장신구'),
(60140, '레트레스 타이드 셉터', '먼지와 진흙으로 뒤덮여 있다'),
(60142, '지그노의 배송', '상단에 메모가 붙어 있습니다.'),
(60149, '신비로운 소 두루마리', '그것이 당신을 부릅니다.'),
(60160, '자이로나우티컬 컴퍼스', '굉장히 복잡해 보이네요'),
(60162, '터보차지 흔들림 방지 발포 디스크', '터보차저처럼 강력하고 흔들림이 없습니다.'),
(60172, '샤른스 헤드', '무리 우두머리 샤른의 잘린 머리'),
(60173, '달토스의 반지', '용기의 상징'),
(60174, '듀크가 보낸 편지', '그렐다 공작부인에게 보내는 봉인된 편지.'),
(60175, '달토스의 인장', '지혜의 상징'),
(60187, '조르지의 황금 귀걸이', '이건 진짜 순금이에요.'),
(60188, '잊혀진 고서', '잡초와 진흙으로 뒤덮여 낡아 보이지만, 책은 온전한 상태인 것 같다.'),
(60189, '달토스의 보석함', '달토스 가문의 문장이 새겨진 뚜껑이 있는, 화려하게 장식된 보석함.'),
(60190, '나르겔라스의 편지', '피어스에게 보내는, 봉인된 편지 한 통.'),
(60191, '멜레나의 소지품', '먼지가 쌓인 낡은 상자 안에는 다양한 마법 용품과 책들이 들어 있었다.'),
(60196, '고기 덩어리', '크래그터스크 고기 덩어리'),
(60197, '스토른스 헤드', '산적 두목 스토른의 머리'),
(60201, '로데론의 찢어진 깃발', '당신의 승리를 증명하는 증거입니다.'),
(60240, '반짝이는 황동 열쇠', '희미한 마법으로 은은하게 반짝인다'),
(60242, '마법에 걸린 황동 열쇠', '강력한 신비로운 마법이 소용돌이치고 있다.'),
(60244, '조율된 황동 키', '강력하고 신비로운 마법에 매료되고 그 마법과 조화를 이루게 되었습니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(60246, '대형 러그넛 링', '크기가 큰 철제 너트에 깨끗하고 커다란 옥이 박혀 있습니다.'),
(60258, '부패의 왕관', '악마의 마법으로 봉인되었다.'),
(60260, '유령의 매력', '묘한 기운이 감돌고 있다.'),
(60261, '퍼볼그 단서 #1', '악취가 나고 오염된 수액이 담긴 작은 병.'),
(60262, '퍼볼그 단서 #2', '혐오스러운 기운을 끌어당기는 듯한 뒤틀린 장식품.'),
(60263, '퍼볼그 단서 #3', '알 수 없는 기호가 새겨진 다양한 조각 돌들이 가득 담긴 가방.'),
(60281, '반짝이는 녹색 비늘', '눈부신 초록빛 마법 속에서 반짝인다.'),
(60293, '단련되지 않은 룬블레이드', '어둠과 목소리 없는 힘이 당신에게 이 검을 들라고 손짓합니다.'),
(60307, '\'슬립\' 단검', '작은 보석들로 장식되어 있습니다.'),
(60308, '오일이 함유된 장갑', '그 냄새는 황홀하다'),
(60309, '\'제이드우드\' 롱보우', '밴드에는 밝은 색의 옥이 박혀 있다.'),
(60314, '축복의 두루마리', '밝은 금색 잉크로 쓰인 성경 구절이 포함되어 있습니다.'),
(60315, '칼라두스의 오브', '성스러운 에너지로 밝게 빛난다'),
(60335, '검은바위 시그넷', '고대 오크 문자로 뒤덮여 있다.'),
(60336, '마울 오브', '고대 오크 문자로 뒤덮여 있다.'),
(60378, '살론의 반지', '커다란 자수정이 박혀 있고 키린 토의 표식이 새겨져 있습니다.'),
(60391, '피어스의 지시사항', '오래된 피의 해방 마법을 재현하는 방법에 대한 설명입니다.'),
(60392, '라네론의 검', '제2차 세계 대전의 영웅이 휘둘렀던 검.'),
(60393, '마텔라의 방패', '빛의 소녀에게 속한 것이었다.'),
(60397, '부서진 검술가의 검', '부러졌지만 여전히 날카롭다.'),
(60398, '부서진 블레이드마스터의 칼날', '오크 문자가 검에 새겨져 있다. 오래전에 잊혀진 언어로, 옛 검술의 달인들만이 알고 있던 언어다.'),
(60416, '그라르의 해골', '살아있을 땐 고집불통, 죽어서도 굳은 두개골을 가진 자.'),
(60419, '네크롤라이트의 얼굴', '눈빛에 희미한 섬광이 서려 있어, 누군가 당신을 지켜보고 있다는 느낌이 든다.'),
(60422, '잭 더 리퍼', '셀 수 없이 많은 종류의 독으로 뒤덮여 있으며, 그중 일부는 차마 이름조차 언급하지 않는 것이 낫다.'),
(60426, '경비대장 흉갑', '피로 뒤덮여 있다.'),
(60436, '눈먼 가죽 후드', '시력 상실은 다른 감각을 예민하게 만든다.'),
(60442, '유산의 하크탈즈', '블러드스칼프 가문의 선조 도끼로, 이 무기가 강력한 맹금류 발게쉬를 처치했다고 전해진다.'),
(60443, '완벽하게 포장된 선물', '정성과 사랑을 담아 포장했습니다.'),
(60444, '밀가루 한 포대', '모든 맛있는 음식이 그렇듯, 양념이 듬뿍 들어있습니다.'),
(60462, '아리덴의 상자', '유령 같은 기운으로 가득 차 있다.'),
(60470, '카네크누운의 얼음 진주', '북해 저 멀리에서 온 진주처럼, 얼음의 정수를 담아 반짝이는 섬.'),
(60476, '깨끗한 고릴라 가죽', '새것과 다름없는 완벽한 상태입니다.'),
(60477, '붉은해적단 보급 상자', '새것과 다름없는 완벽한 상태입니다.'),
(60485, '디아블로 2 파괴의 군주 소장판 (미개봉)', '최상급 상태입니다.'),
(60486, '피쉬브링어', '빛의 순수한 에너지로 반짝이는 그것은 살아있는 것일까?'),
(60487, '무우 로드의 망토', '그의 위엄이 망토에서 느껴진다.'),
(60488, '무리의 드레이프', '우유처럼 부드러운 힘이 담겨 있습니다.'),
(60489, '소 전문가의 모자', '소 울음소리의 에너지가 가득 담겨 있습니다.'),
(60490, '소가죽 모자', '순수한 우아함에 무무 감성을 더했습니다.'),
(60491, '무 스톤', '소들이 지배하던 시절의 이미지가 그 안에 담겨 있다. 그것은 마음속 깊이 각인되며, 그 힘은 거의 압도적이다.'),
(60517, '변색된 목걸이', '이 은 목걸이는 세월의 흔적을 고스란히 간직하고 있습니다. 묵은 때 아래로 반짝이는 사파이어들이 물결치는 듯한 줄기를 따라 장식되어 있는데, 그 모습은 마치 중앙의 금빛 원반에서 뻗어 나온 햇살을 연상시킵니다.'),
(60518, '브로큰 코어 펜던트', '분석기 구조물의 부서진 핵심 부품으로 만든 부적.'),
(60536, '다크윈드 글레이브', '부패 척결에 완벽하게 균형이 잡혀 있습니다.'),
(60551, '얼굴 없는 자의 펜던트', '초현실적인 분위기를 자아낸다.'),
(60553, '그을음 부츠', '두꺼운 그을음층으로 덮여 있음'),
(60577, '헤이트포지 손아귀', '분노와 맹렬함으로 공격하라.'),
(60585, '크로콜리스크 티어 그로그', '악어의 눈물을 짜서 만들었습니다.'),
(60586, '"커다란 도마뱀 고기가 가득 든 큰 자루"', '냄새가 지독해.'),
(60587, '타르그의 우정의 바위', '새로운 친구에게! 사랑해.'),
(60588, '위더바인 늪지 야수 핵', '끈적거리고 냄새가 나요.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(60593, '얄의 육즙 가득한 점블리', '향기가 예상외로 좋네요.'),
(60598, '야를의 패키지', '"냄새가 정말 지독하네요."'),
(60622, '아카데미의 반지', '신비예술과학아카데미를 대표하여 수여되었습니다.'),
(60672, '활성화된 골렘 코어', '중심부에서 강력한 에너지가 뿜어져 나온다.'),
(60683, '골드 코스트 배송', '작은 메모가 붙어 있습니다.'),
(60702, '깨진 플라스크', '신맛이 난다.'),
(60703, '찢어진 노동조합 전단지', '광부가 당신을 가리키며 노조에 가입하라고 촉구하는 모습을 묘사하고 있습니다.'),
(60705, '균열된 파워 코어', '갈라진 틈에서 녹색 액체가 천천히 흘러나오고 있다.'),
(60706, '재로 덮인 두루마리', '라그나로스를 찬양하는 찬송가가 수록되어 있습니다.'),
(60720, '워그 트랩', '블랙록 워그가 안에 들어갈 만큼 충분히 크다.'),
(60739, '변색된 랜슬롯 반지', '잊혀진 가문의 문장을 지니고 있다.'),
(60770, '와이번 둥지 새끼', '이 작은 모습일지라도 와이번은 사납다.'),
(60775, '매뉴얼: 개입', '멀리 떨어진 동맹국에 해를 끼치는 것을 막는 방법에 대한 가르침을 담고 있습니다.'),
(60789, '핀클의 액셀러레이터', '시간 팽창 보장! 핀클 아인혼은 오작동 및 노화로 인한 조기 사망에 대해 책임을 지지 않습니다.'),
(60804, '추억의 그림자', '그것의 그림자는 당신 자신의 그림자를 떠올리게 합니다.'),
(60807, '무덤 도굴꾼의 발걸음', '그는 탐욕에 눈이 멀어 스스로 무덤을 팠다.'),
(60853, '꿈틀거리는 엘프 귀의 쌍', '아주 작은 소리에도 귀를 쫑긋 세운다.'),
(60854, '초대 칸의 피', '내 혈육의 피.'),
(60855, '만족의 의식 먼지', '마음속 깊은 곳을 뒤흔든다.'),
(60859, '테라드라의 눈물', '감정으로 반짝인다.'),
(60860, '움직이는 원소의 삼지창', '움직임을 멈추면 심장이 조바심 나게 뛰기 시작합니다.'),
(60872, '폭죽 바지', '나즈의 백업 선수로 알려져 있다.'),
(60885, '제3대 칸의 다르카르', '제3대 칸 시대에 휘둘러졌던 강력한 장도끼.'),
(60902, '겔키스 어스바인더', '지구와 조화를 이루며.'),
(60905, '제2대 칸의 바투카르', '대지의 지팡이는 2대 칸 시대에 사용되었던 무기이다.'),
(60915, '듀로타르 밴드', '듀로타르 제2차 전투 중 영웅적인 행위를 기리며.'),
(60916, '듀로타르의 인장', '듀로타르 제2차 전투 중 영웅적인 행위를 기리며.'),
(60917, '듀로타르의 반지', '듀로타르 제2차 전투 중 영웅적인 행위를 기리며.'),
(60925, '스톰스타우트 서프라이즈 스타인', '이 마법에 걸린 맥주잔에는 첸의 깜짝 음료가 절대 떨어지지 않는 것 같다!'),
(60982, '프로그래머 양말', '편안하면서도 실력 향상에 도움이 됩니다.'),
(60984, '아이스포 쿠키', '초콜릿 칩!'),
(60988, '보마른의 행운의 양말', '예상외로 따뜻하고 편안했어요.'),
(60989, '이상한 양피지', '이 글의 내용을 전혀 이해할 수 없지만, 중요한 내용이라는 느낌은 듭니다.'),
(61006, '무한의 신비의 칼날', '시간의 동굴을 흐르는 시간의 모래를 녹여 만든 유리로 만들어졌습니다.'),
(61011, '플린트록의 핸드 캐논', '마못 사냥에도 좋습니다.'),
(61030, '머크피셔', '물고기도 잡고 적도 잡는다.'),
(61059, '모스하트의 심장', '들쭉날쭉하면서도 순수하다.'),
(61064, '엘드레스 밴드', '이 고대의 반지는 마법에 심취한 하이본 엘프들이 착용했던 것이다.'),
(61065, '헬파이어 사바톤', '이 부츠는 아웃랜드에서 가져온 금속으로 제작되었습니다.'),
(61068, '검은무쇠 모독자', '진정한 다크 아이언 건축의 결정체.'),
(61081, '맹렬함의 선물', '세나리우스의 축복을 받은 이 선물은 자연의 맹렬함을 ​​고스란히 보여줍니다.'),
(61082, '콜드하울의 목걸이', '스노우 예티의 기념품.'),
(61092, '골든 텔 컴퍼니 코인', '정말 특별한 거예요, 약속드려요.'),
(61100, '갑판장 표창', '쿨 티란 해군 소속으로 복무 중입니다.'),
(61104, '악마 [나이트 엘프, 남성만 해당]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(61105, '악마 사냥꾼 [나이트 엘프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(61106, '강령술사 II [나이트 엘프, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(61154, '야만적인 창', '간단하지만, 엄청나게 효과적이다.'),
(61155, '원시적인 구슬 목걸이', '대부분의 사람들의 입맛에는 맞지 않을 거예요.'),
(61156, '백 개의 깃털로 된 머리띠', '몇 개 잃어버린 것 같네요.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(61187, '정교한 자이로스코프 고글', '연동 메커니즘은 장거리 사격 시 시야를 넓혀줍니다!'),
(61209, '악몽의 조각', '정화 과정을 거친 후에는 잠깐이라도 보는 것만으로도 악몽을 꾸게 될 수 있다.'),
(61214, '깨어나는 자의 망토', '한때 각성의 시작을 알리기 위해 착용되었던 것.'),
(61237, '각성의 망치', '이끼로 뒤덮여 때를 기다리고 있다.'),
(61248, '야수 사냥꾼의 블런더버스', '개머리판에는 G.G.라는 이니셜이 새겨져 있습니다.'),
(61263, '팩로드의 이빨', '두꺼운 갑옷을 뚫는 데는 일가견이 있다.'),
(61308, '길네아 정의의 망치', '길네아 법에 대한 최종 결정권을 지닌 유물.'),
(61312, '블랙 펜던트', '소용돌이치는 마법은 어두운 생각들을 유혹한다.'),
(61328, '울프블러드', '그레이메인 가문 내에서 대대로 전해 내려오는 것이다.'),
(61368, '그레이메인 휘장', '한때 고귀했던 길니아스의 문장입니다.\\N'),
(61369, '레이븐셔 타바드', '역사와 전통이 깃든 레이븐샤이어의 문장을 자랑스럽게 새긴 휘장입니다.\\N'),
(61392, '회로도: 고에너지 조절기', '지나치게 복잡하고 정교한 디자인.'),
(61406, '워겐의 표식', '송곳니와 발톱으로 너는 다시 태어난다.'),
(61447, '모스그로브 가족 빗자루', '손잡이가 10개, 헤드가 16개 새로 교체되었습니다.'),
(61450, '마음의 열쇠', '열린 마음은 다른 많은 가능성을 열어줍니다.'),
(61457, '수수께끼의 편지', '이 편지에는 불안감이 맴돌고 있다.'),
(61465, '죽음의 펜던트', '악마와의 계약, 피로 서명된 계약...'),
(61517, '키메라의 눈', '이 마법의 보석은 인간의 갑옷이든 괴물의 갑옷이든 견딜 수 없는 부식성 독을 천천히 내뿜는 것 같습니다.'),
(61520, '황금 바나나', '유인원들을 지배하는 힘을 지녔지만, 끔찍한 저주에 시달리고 있다.'),
(61525, '자연의 부름', '님프의 총애를 받는 존재.'),
(61527, '솔니우스의 숨결', '생명의 에너지로 가득 차 있다.'),
(61532, '그랜드 슬래머', '너무 무거워요...'),
(61534, '피셔의 작살', '어부는 지금 어디에 있을까 궁금하네...'),
(61541, '레타샤즈의 오른발톱', '나머지 발톱 하나가 없습니다.'),
(61545, '섀도플레어의 문장', '수많은 트롤들의 기운으로 더욱 강해졌다.'),
(61572, '가트사이드 패밀리 렌치', '시제품 측면에 박혀 있는 이 렌치는 전성기를 훨씬 지났음을 알 수 있습니다.'),
(61577, '중위의 검', '칼자루에는 L.P.라는 이니셜이 새겨져 있습니다.'),
(61615, '불타는 횃불', '날씨가 너무 덥다!'),
(61674, '과다 청구된 레이 에너지', '폭발적인 에너지가 순수한 형태로 응축되었다.'),
(61680, '녹슨 회중시계', '그레이메인 성벽이 무너진 바로 그 순간부터 작동을 멈춘 것 같습니다.'),
(61681, '찢어진 손수건', '피투성이였다.'),
(61682, '부러진 지팡이', '귀족들조차 예외는 아니었다.'),
(61683, '파손된 석궁', '어떻게 된 일인지 아직 작동은 하네요.'),
(61684, '워겐의 머리카락 뭉치', '마른 피 냄새가 나요.'),
(61685, '구멍 뚫린 화살통', '구멍투성이야.'),
(61686, '깨진 보호자', '복구 불가능.'),
(61687, '귀족의 펜던트', '마법은 거의 사라졌다.'),
(61688, '워겐 클로', '여전히 치명적이다.'),
(61689, '낡은 책', '글자가 알아볼 수 없습니다.'),
(61690, '성직자의 구부러진 지팡이', '빛은 당신이 옳다고 믿는 모든 대의를 위해 봉사합니다. 아무리 사악하더라도 말입니다.'),
(61692, '부서진 헬멧', '머리 위로 날아온 강풍으로 헬멧이 작동 불능 상태가 되었다.'),
(61700, '시간의 구조', '잘 찢어지는 재질입니다.'),
(61701, '변형된 자의 랩', '원래는 판금 투구였지만, 시간의 흐름에 의해 얇은 천으로 변형되었지만 그 본래의 성질은 그대로 간직하고 있다.'),
(61754, '딥우드 파이프', '한 모금만 마셔도 사용자는 의식을 잃을 수 있습니다.'),
(62008, '가시나무', '터질 것 같아.'),
(65003, '희생의 예복', '모든 것에는 대가가 있다.'),
(65004, '화려한 혈석 단검', '그것은 굶주리고 있다...'),
(65008, '드림스 헤럴드', '깨어있는 상태와 꿈꾸는 상태 사이.'),
(65020, '아마니 휘슬', '조히크가 준 선물입니다.'),
(65029, '개요: 멀록 지느러미', '이것들을 사용하면 정말 수영 속도가 빨라져요!')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(65031, '개요: 수리된 전자식 랜턴', '석유가 고갈될 때 당신의 구세주가 되어줄 것입니다.'),
(65105, '깨어나는 자의 척도', '다른 사람들이 잠들 수 있도록 한 사람이 기다려야 한다.'),
(67000, '사랑스러운 핑크 여우', '수줍음이 많은 분홍여우는 자신과 친해진 존재에게만 모습을 드러냅니다.'),
(67001, '4주년 기념 선물 (온라인 가입 4주년)', 'Turtle WoW가 4주년을 맞았습니다! 세계 최고의 게임 커뮤니티가 되어주셔서 진심으로 감사드립니다!'),
(67005, '5주년 기념 선물 (온라인 가입 5주년)', 'Turtle WoW의 5주년을 함께 축하해주세요! 멋진 커뮤니티의 일원이 되어주시고 저희 서버에서 플레이해주셔서 진심으로 감사드립니다!'),
(69000, '길네안 레이븐', '수 세대에 걸쳐 길네아의 까마귀는 왕실 권위의 영원한 상징으로 자리매김했으며, 가장 암울한 밤에도 그레이메인 가문의 지속적인 영향력을 모두에게 일깨워 주었습니다.'),
(69001, '작은 차원의 추적자', '빠를 뿐만 아니라 소리도 엄청 크다!'),
(69002, '스카티', '독창적이고 지능적인 천재적인 공학 기술의 산물!'),
(69003, '팔', '커다란 눈과 도도한 미끄러짐이 특징입니다.'),
(69004, '펭귄', '그 외형은 결투사들이 턱시도를 입고 결투를 벌이던 보다 문명화된 시대를 떠올리게 합니다.'),
(69006, '글리터윙', '이 날아다니는 생물들은 야생에서 깃털을 떨어뜨리지 않습니다. 만약 깃털이 몸에서 떨어지더라도, 그 깃털은 잠시 동안 찬란하게 빛나다가 시야에서 사라집니다.'),
(69170, '상아빛 멧돼지', '전설적인 아감마간의 후손으로 여겨지는 이 멧돼지들은 이제 가시덩굴 부족이 귀하게 여기는 동료이자 탈것입니다.'),
(69171, '역병에 걸린 멧돼지', '놀라울 만큼 질긴 멧돼지조차 스컬지의 압도적인 힘 앞에서는 버틸 수 없습니다.'),
(69172, '갑옷을 두른 갈색 멧돼지', '가장 강한 멧돼지만이 갑옷을 두르는 영예를 얻습니다.'),
(69173, '검은 멧돼지', '모험을 즐기는 사나운 동료, 검은 멧돼지를 소환합니다!'),
(70003, '호크스피어의 목걸이', '줄에 꿰어진 여러 가지 뼈들.'),
(70006, '잎으로 덮인 어깨받침', '위장용으로 제작됨'),
(70009, '개구리 주스', '갓 짜낸 개구리 주스.'),
(70016, '무한 새끼', '그는 지금 시간이 몇 시인지 정확히 알고 있을 거예요.'),
(70030, '목재', '잘 타는 마른 통나무.'),
(70033, '타잔의 상아', '적에게서 빼앗은 전리품.'),
(70035, '녹슨 삽', '손잡이에 S.Y.라는 이니셜이 휘갈겨 쓰여 있다.'),
(70045, '녹슨 삽', '손잡이에는 S.Y.라는 두 글자가 새겨져 있습니다.'),
(70046, '은반지', '순은으로 제작되었습니다.'),
(70050, '불행의 어깨 보호대', '난쟁이의 쪼그라든 머리보다도 운이 없군.'),
(70052, '스코그림의 잃어버린 벨트', '얘야, 걔가 그걸 찾도록 도와주는 게 좋겠어.'),
(70053, '로트웜 다리판', '약간 불편하긴 하지만, 그래도 세련되긴 하네요.'),
(70054, '웜하트 부츠', '용의 심장이 들어갈 만큼 크다.'),
(70055, '잊혀진 용기의 흉갑', '잊혔지만, 잃어버린 것은 아니다.'),
(70056, '고대 왕들의 뿔 달린 투구', '왕실급 유물.'),
(70226, '고대의 알파레 텍트', '무술과 전략 전술을 담은 글입니다. 싸움의 섬 전사들이 특히 탐낸다고 합니다.'),
(80000, '황금 용매 새끼', '실버문에서 용매 사육사들에게 한때 귀하게 여겨졌던 종입니다. 밤에는 포식자의 눈에 잘 띄기 때문에 어릴 때부터 주변 환경에 대한 경각심을 키우는 것이 중요합니다.'),
(80001, '탈라시안 텐더', '이 나무는 언제나 춤추듯 깨어나요. 정말 행복한 작은 나무네요!'),
(80003, '검은발여우', '추운 밤이면 이 동물들은 복슬복슬한 꼬리를 담요처럼 사용하여 따뜻하게 지냅니다.'),
(80004, '장난꾸러기 원숭이', '장난기 넘치는 성격과 귀여운 행동으로 가득한 이 아기 원숭이들은 아제로스에서의 모험을 더욱 즐겁게 만들어 줄 완벽한 동반자입니다.'),
(80006, '신비로운 정령', '어둠 속에서 이 작은 정령은 은은한 푸른빛을 무한히 발산합니다.'),
(80007, '마법의 빗자루', '하이 엘프 견습생이 만든 이 빗자루는 누군가 멈추는 방법을 알아낼 수만 있다면 엄청나게 유용할 것이다.'),
(80008, '시간의 청동 원반', '크로미가 시간의 통로 주변의 균열을 닫기 위해 당신에게 준 것이지만, 그 에너지는 어디로 가는 걸까요?'),
(80010, '자정', '한밤중에 달과 함께 (그리고 이 털북숭이 수염 난 마녀와 함께) 말을 타고 달려보세요!'),
(80060, '전쟁의 문양', '더 이상 PvP 모드를 비활성화할 수 없지만, 모든 경험치 획득량이 증가합니다. 이 효과는 레벨 60 달성 후에도 지속됩니다.'),
(80111, '재로 덮인 튜닉', '누군가 여기까지는 왔지만... 끝내 빠져나가지는 못한 모양입니다.\\N'),
(80175, '크로미의 회중시계', '아제로스에서는 시간이 다르게 흐릅니다. 시간을 확인해 보는 게 좋을 거예요.'),
(80180, '저주받은 왕관', '모든 희망을 버리세요...'),
(80181, '저주받은 자들의 요새', '우리의 운명은 누구도 빼앗을 수 없다...'),
(80182, '저주받은 자들의 사바톤', '나는 영원한 고통으로 가는 길이다...'),
(80183, '저주받은 자들의 차우세', '이들은 가장 어두운 영혼들 사이에 살고 있다...'),
(80184, '저주받은 자의 허리띠', '이제 눈먼 세상 속으로 내려가 봅시다...'),
(80185, '저주받은 자들의 손아귀', '여기서는 연민이란 그것이 죽었을 때에만 살아남는다...'),
(80186, '저주받은 자의 견장', '우리도 한때는 남자였지...'),
(80187, '불멸의 수호자의 타바드', '군중 속에서 진정한 게이머를 어떻게 알아볼 수 있을까요? 굳이 찾을 필요는 없습니다. 그들은 당신이 알아차릴 수 있도록 확실히 보여줄 테니까요.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(80300, '시간 감시자의 타바드', '시간의 순수성을 지키는 막중한 임무가 당신에게 맡겨졌습니다. 비록 다른 것을 바라는 이들이 있을지라도, 진정한 시간의 흐름은 오직 하나뿐임을 알아야 합니다.'),
(80301, '세나리온 서클 타바드', '자연과의 조화가 천에 고스란히 짜여 있습니다.\\N'),
(80303, '아이언포지 타바드', '대용광로의 열기가 느껴지는 드워프의 유산입니다.\\N'),
(80304, '다크스피어 부족 타바드', '검은창 부족의 사나운 문장입니다.\\N'),
(80305, '다르나수스 타바드', '다르나서스의 고요하고 우아한 분위기를 닮은 차분하고 자연스러운 모습입니다.\\N'),
(80306, '그노메레간 타바드', '놈리건 최고의 발명가들이 지닌 기발함이 이 휘장에 담겨 있습니다.\\N'),
(80307, '오그리마 타바드', '오그리마의 붉고 검은 깃발로, 호드의 강인한 생명력을 상징합니다.\\N'),
(80308, '썬더 블러프 타바드', '대지모신의 정신을 품고 있습니다.\\N'),
(80309, '언더시티 타바드', '자신의 운명을 스스로 개척하는 이들의 표식을 지녔습니다.\\N'),
(80310, '신도레이 타바드', '위엄 있고 세련된 블러드 엘프의 깃발입니다.\\N'),
(80311, '실버핸드 타바드', '빛의 유산을 이어가는 이들을 위한 것입니다.\\N'),
(80312, '와일드해머 타바드', '와일드해머의 굳센 의지를 보여 주는 투박한 상징입니다.\\N'),
(80314, '언데드 스컬지 타바드', '공포의 표식입니다. 스컬지의 역병을 퍼뜨리는 자들이 사용합니다.\\N'),
(80317, '퀘르탈라스 타바드', '고대의 영광을 상징하는 쿠엘탈라스의 문장입니다.\\N'),
(80320, '스톰윈드 타바드', '스톰윈드의 사자는 보는 모든 이에게 용기를 불어넣습니다.\\N'),
(80400, '쿼크스 쉑 멤버십 카드', '고객의 약점을 파악하여 그를 더욱 효과적으로 이용하십시오.'),
(80410, '하이 엘프 고아 호루라기', '돌보기로 한 고아를 불러들였다가 돌려보내세요.'),
(80423, '졸마진의 부두 인형', '인형은 전쟁지도자 졸마진과 유사합니다.'),
(80425, '흰 사슴', '강렬하고 아름다운 존재.'),
(80430, '장갑 스펙트럴 타이거', '역사학자들은 이 무형의 짐승들이 드레노어가 폭발하면서 방출된 에너지로 인해 세계의 동식물이 변형되었을 때 생겨났다고 주장합니다.'),
(80431, '스위프트 매직 루스터', '천재의 손에 든 마법은 놀랍고 기적적인 일들을 해낼 수 있다. 하지만 바보의 손에 든 마법은 거대한 수탉을 만들어낼 뿐이다.'),
(80433, '흑곰', '덩치도 크고, 싸울 준비도 되어 있고, 게다가 곰이잖아요. 탈것으로 뭘 더 바라겠어요?'),
(80438, '갈색곰', '덩치도 크고, 싸울 준비도 되어 있고, 게다가 곰이잖아요. 탈것으로 뭘 더 바라겠어요?'),
(80443, '장갑 맥주 축제 램', '드워프들은 이 품종의 온화한 성격이 엄격한 훈련 덕분이라고 말하지만, 다른 종족들은 매일 독한 맥주를 마시는 것이 그 이유 중 하나라고 주장합니다.'),
(80446, '장갑 나이트세이버', '나이트 엘프의 탈것이 죽으면, 기수는 추모의 표시로 그 검의 거대한 송곳니 하나를 간직하는 것이 관례입니다.'),
(80447, '갑옷 입은 무리 늑대', '만약 무언가를 가져오라고 부탁받으면, 아마도 작은 포유류나 인간형 동물의 머리를 가져올 가능성이 높습니다.'),
(80449, '장갑 동맹군 말', '전투 중 충돌을 견딜 수 있도록 장갑으로 보호됩니다.'),
(80455, '장갑 맥주 축제 코도', '맥주 축제의 즐거운 분위기를 기념하는 축제의 언덕.'),
(80457, '갑옷을 입은 탈라시안 유니콘', '마법 갑옷으로 보호받는 신화 속 생물로, 우아함과 힘을 구현한다.'),
(80458, '화려한 탈라시안 유니콘', '신비로운 쿠엘탈라스 숲에서 온 위풍당당한 탈것.'),
(80459, '흰색 탈라시안 유니콘', '희귀하고 신비로운 생물로, 아름다움과 우아함을 중시하는 이들이 탐내는 존재입니다.'),
(80460, '레드 로켓 자동차', '항상 제한 속도보다 시속 20마일 더 빠르게 달리세요.'),
(80461, '그린 로켓 자동차', '얘야, 안전벨트 매!'),
(80462, '블루 로켓 자동차', '에어백은 포함되어 있지 않습니다.'),
(80463, '보이지 않는 패션: 허리의 여름 수집품', '허리(waist)에는 정말 아까운(waste) 물건이군요!'),
(80499, '길드 이름 변경 토큰', '이 아이템을 사용하려면 길드 마스터여야 합니다. 길드 ​​이름을 변경하려면 `.guildname "새 이름"` 명령어를 사용하세요.'),
(80555, '애완동물 나메 치아응에 토큰', '현재 소환한 소환수의 이름을 바꾸려면 .petname 명령어를 사용하세요.'),
(80648, '환상: 그놀', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(80650, '하이 엘프 헤어 염색약: 해바라기 블론드', '모든 것이 꼬이기 직전 태양이 마지막으로 반짝이는 듯한 옅은 황금빛 금발입니다.\\N'),
(80651, '하이 엘프 헤어 염색약: 애쉬 블론드', '새벽의 마법 수정처럼 차갑게 빛나는 얼음빛 금발입니다.\\N'),
(80652, '하이 엘프 헤어 염색약: 루비 러쉬', '진홍색입니다. 자신의 혈통이 여전히 예전만큼 고귀하다고 믿는 이들에게 어울립니다.\\N'),
(80653, '하이 엘프 헤어 염색약: 시나몬 브라운', '가을 저녁의 고요함을 닮은 짙은 적갈색입니다.\\N'),
(80654, '하이 엘프 헤어 염색약: 밀색 갈색', '더 밝은 날을 향해 이끄는 따뜻한 햇살 같은 구릿빛 금발입니다.\\N'),
(80655, '하이 엘프 헤어 염색약: 샌드 블론드', '고개를 돌리는 것만으로 누군가의 눈을 멀게 할 정도로 밝은 금발입니다.\\N'),
(80656, '하이 엘프 헤어 염색약: 코랄 레드', '불타는 듯한 적주황색입니다. 태양샘처럼 어떤 약속은 너무 뜨거워 감당하기 어렵죠.\\N'),
(80657, '하이 엘프 헤어 염색약: 허니 블론드', '마법이 역류하기 직전 마지막 희망처럼 반짝이는 황금빛 금발입니다.\\N'),
(80658, '하이 엘프 헤어 염색약: 별이 빛나는 밤', '비전 마법 사고를 수습하느라 지새운 끝없는 밤처럼 짙은 한밤중의 파란색입니다.\\N'),
(80659, '하이 엘프 헤어 염색약: 게 다리', '마법에 너무 많이 도박을 건 뒤 남는 후회처럼 창백한 크림빛 구리색입니다.\\N'),
(80660, '고블린 헤어 염색약: 구리색', '노움의 장치에서 \'빌려 온\' 전선처럼 반짝이는 구리색입니다. 남성 고블린용 염색약은 그을음 때문에 기본적으로 더 검게 나옵니다!\\N'),
(80661, '고블린 헤어 염색약: 루비', '묘기를 부리다 실패했을 때 달아오르는 얼굴처럼 짙은 붉은색입니다. 쾅쾅, 이런! 남성 고블린용 염색약은 아직 폭발하지 않은 밝은 구릿빛 갈색입니다!\\N')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(80662, '고블린 헤어 염색약: 빨간색', '계산을 조금 잘못한 뒤의 장부처럼 선명한 붉은색입니다. 걱정 마세요. 남성 고블린 쪽은 갈색이니까요!\\N'),
(80663, '고블린 헤어 염색약: 보라색', '언더마인 조명처럼 보랏빛입니다. 번쩍이고, 부서지고, 곧 폭발할 것 같죠. 남성 고블린용 염색약은 그 조명을 잇는 구리 전선 같은 색입니다. 반짝이네요!\\N'),
(80664, '고블린 헤어 염색약: 검정색', '검은바위 섬 위에 드리운 연기처럼 어둡습니다.\\N'),
(80665, '하이 엘프 헤어 염색약: 아주르 스카이', '하늘만큼이나 큰 자존심을 머리 위에 얹고 싶다면 잘 어울리는 하늘빛 파랑입니다.\\N'),
(80692, '불멸의 챔피언의 차저', '하지만 가장 중요한 규칙, 절대 잊어서는 안 될 규칙은, 아무리 울고 애원해도 자정 이후에는 절대 먹이를 주지 않는 것입니다.'),
(80694, '환상: 재앙', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(80699, '외형 변경 토큰', '원하는 외형을 가진 동일 종족의 새 캐릭터를 생성한 다음, `.copy name` 명령어를 사용하여 해당 외형을 이 캐릭터에 복제하세요.'),
(80700, '트라이벌 트로그 클럽', '그냥 큰 뼈일 뿐이야.'),
(80715, '들어 올려진 컵의 장갑', '건배! 우리가 이 요새를 영원히 지배하길!'),
(80724, '셀 히터', '가장 추운 밤에도 따뜻함을 유지해 줍니다.'),
(80727, '깨진 병', '다크샤이어 밀주 III'),
(80737, '방사선 조사된 링', '어떤 것도 방사능을 제거할 수 없습니다.'),
(80738, '바실리스크 비늘 부츠', '불쌍한 촘퍼...'),
(80745, '혐오스러운 석궁', '끔찍한 갈비뼈와 바느질로 만들어졌어. 정말 소름 끼쳐.'),
(80772, '뒤틀린 드레나이 갈비뼈', '머나먼 나라에서 온 기념품.'),
(80773, '다미엔의 슬픔', '팔이 찢어졌다.'),
(80775, '잭 더 리퍼', '이 칼이 목격한 잔혹한 일들의 기억은 당신에게 공포를 불러일으킵니다.'),
(80781, '실험 D2X3', '흥미로운 결과네요. -콜리'),
(80784, '끊어지지 않은 죄수 수갑', '저주받은 남자의 불굴의 의지와 강인한 정신은 여전히 ​​금속 속에 메아리치고 있다...'),
(80805, '프리즘형 결정', '끊임없이 색이 변하고, 결코 똑같지 않다.'),
(80815, '실리시드 알', '흔들리고 있어요!'),
(80824, '나릴라산즈의 이빨', '불꽃 모양의 룬 문자가 이빨에 새겨져 있다.'),
(80840, '흑요석 구체', '구체 안에는 끝없이 깜빡이는 빛이 갇혀 있다.'),
(80866, '사랑스러운 사과', '싱싱한 초록 사과.'),
(80868, '노비의 벨트', '안쪽에 암호화된 메시지가 적혀 있습니다.'),
(80878, '아마니 이글', '이 새들은 종종 거북이를 높은 곳에서 떨어뜨려 등껍질을 깨뜨려 사냥합니다.'),
(81015, '요리사의 앞치마', '심술궂은 냄새가 나네.'),
(81024, '던브레이커의 결혼반지', '죽음조차도 우리를 갈라놓을 수 없어.'),
(81025, '모르비드의 결혼반지', '죽음조차도 우리를 갈라놓을 수 없어.'),
(81059, '폭스의 영혼석', '그것은 안개처럼 조용하고 신비롭게 사라진다.'),
(81060, '강화된 룬검', '마음 깊은 곳에서는 파괴를 자행하고 싶은 억누를 수 없는 갈망이 느껴집니다.'),
(81077, '테라모어 타바드', '테라모어 자체처럼 굳건합니다.\\N'),
(81079, '금박 붉은십자군 휘장', '영광을 위해 금빛으로 장식한 붉은십자군의 열정입니다.\\N'),
(81081, '분노의 타바드', '멈추지 않는 분노가 힘을 불어넣습니다.\\N'),
(81082, '빛나는 타바드', '눈부신 광휘의 상징입니다.\\N'),
(81083, '공허의 타바드', '어두운 공허가 시선을 끌어당깁니다.\\N'),
(81084, '마법의 타바드', '비전의 힘을 천에 짜 넣었습니다.\\N'),
(81085, '자연의 타바드', '자연의 정령을 녹색에 담았습니다.\\N'),
(81087, '여름 불꽃의 타바드', '여름 햇살처럼 따뜻합니다.\\N'),
(81088, '여름 하늘의 타바드', '가장 긴 낮을 기념하며 태양의 문장을 자랑스럽게 달았습니다.\\N'),
(81089, '듀로타르 노동조합 타바드', '듀로타 노동자들의 연대를 상징합니다.\\N'),
(81091, '빅 블리자드 베어', '신나는 모험을 떠나기 전, 소중한 꼬마 승객을 안전벨트로 단단히 고정하는 것을 잊지 마세요.'),
(81098, '레반투스크 타바드', '레반터스크 부족의 자랑스러운 깃발입니다.\\N'),
(81100, '까마귀 군주의 고삐', '나머지는 잊혀지고, 잘린 날개와 수치심에 휩싸여 땅 위를 걷게 될 것이다.'),
(81101, '나이트 엘프 헤어 염색약: 블랙', '이 염색약이 발명되기 전까지만 해도 나이트 엘프에게 검은 머리는 드문 편이었습니다.\\N'),
(81102, '다크문 댄싱 베어', '이 무시무시한 탈것들은 전투 중에 갑자기 춤을 추기 시작하는 버릇이 있는데, 이는 기수들을 몹시 짜증 나게 한다.'),
(81110, '활짝 핀 사랑스러운 장미', '오래가진 않겠지만, 정말 예뻐요.'),
(81111, '파란색 여름 바지', '여름 햇살 아래에서 자유롭게 움직이고 축제를 즐기기 좋게 재단되었습니다.\\N'),
(81116, '피크닉 바구니', '편안한 피크닉을 준비해 보세요.'),
(81118, '쉘코인', '쉘 주식회사 소유의 주식입니다. 사세요! 사세요! 사세요! 시장 가격이 폭등하기 전에 서두르세요!')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(81119, '비행기표', '반짝이는 평원으로 가는 편도 티켓.'),
(81120, '프레이페더 히포그리프', '고대 하이본족의 탈것으로, 잠재된 마법적인 힘 때문에 매우 드물게 발견됩니다.'),
(81121, '세나리온 히포그리프', '세나리온 서클의 구성원들은 동맹인 히포그리프들과 오랫동안 번영하는 협력 관계를 유지해 왔습니다. 갈등이 불가피할 때는 세나리온 전쟁 히포그리프가 소집됩니다.'),
(81122, '블러드폴른 망토', '무고한 자들의 피로 물들어 있다.'),
(81124, '붉은십자군 복수자의 투구', '불타오르는 심장과 발치에 쌓인 이단자들.'),
(81131, '붉은십자군 복수자의 투구', '불타오르는 심장과 발치에 쌓인 이단자들.'),
(81140, '스팀휘들 한정판 웜홀', '스팀휘들 비치 체험으로 안내합니다. 주의: 사용 시 사용자는 스팀휘들 카르텔이 기기 오작동에 대해 책임을 지지 않는다는 점에 동의하는 것으로 간주됩니다.'),
(81142, '키라지 의식용 셔츠', '2021년 2월 13일 — 내가 고대 신 크툰을 물리친 날 (다른 사람들도 몇 명 있었다).'),
(81143, '울둠의 판들', '남아있는 것은 많지 않지만, 어쩌면 수리가 가능할지도 모릅니다.'),
(81145, '환상: 판다렌', '이 변장은 로그아웃할 때까지 유지됩니다.'),
(81150, '피닉스 새끼', '불사조 신 알라르의 자식인 이 새끼는 태어나자마자 곧바로 날아오릅니다.'),
(81151, '스펙트럴 펠링', '이 독특한 요정 용 종은 아제로스에서 흔히 볼 수 있는 종이 아닙니다.'),
(81152, '작은 익룡', '나이가 들면 이 작은 악동들은 원하는 것은 무엇이든 먹어치우고 다른 종의 먹이가 되는 경우는 거의 없습니다.'),
(81153, '갑옷보라색곰', '이 곰처럼 생긴 탈것은 무거운 갑옷 덕분에 더욱 민첩합니다.'),
(81154, '갑옷흑곰', '이 곰처럼 생긴 탈것은 무거운 갑옷 덕분에 더욱 민첩합니다.'),
(81155, '갑옷붉은곰', '이 곰처럼 생긴 탈것은 무거운 갑옷 덕분에 더욱 민첩합니다.'),
(81156, '블랙스톤 드래곤 가드', '용매는 알려진 포식자 가운데서도 손꼽히게 치명적입니다. 먼 거리의 먹잇감도 찾아내 빠르게 덮쳐 발톱과 부리로 찢어 버립니다.\\N'),
(81158, '갑옷을 입은 서리갈기곰', '이 곰처럼 생긴 탈것은 무거운 갑옷 덕분에 더욱 민첩합니다.'),
(81159, '작은 해안 게', '이 절지동물들은 아제로스의 많은 해안가에 서식하며, 그들의 유일한 진정한 욕망인 꼬집기를 실현하고자 합니다.'),
(81182, '갑옷을 입은 다크스피어 랩터', '트롤과 랩터는 서로에게서 속도, 교활함, 그리고 사나움을 존경한다.'),
(81183, '선스케일 해츨링', '이 희귀한 바람뱀의 밝은 비늘은 햇빛을 흡수하여 그늘에서도 따뜻함을 유지합니다.'),
(81185, '에어리 피크 그리폰', '그리폰은 예리한 시력 덕분에 먼 거리까지 볼 수 있고, 기수에게 앞에 닥칠 위험을 경고할 수 있습니다.'),
(81186, '갑옷을 입은 에어리 피크 그리폰', '이 고귀한 그리핀은 얼라이언스 구성원이라면 누구나 바랄 만한 든든한 전투 동반자입니다.'),
(81190, '레드 슈레더 X-0524A', '아제로스의 경이로운 자연을 추출하고 착취하려는 욕망에 의해 움직인다.'),
(81191, '그린 슈레더 X-0524B', '고블린의 파괴적인 본성은 그들의 파쇄기를 통해 가장 잘 드러납니다.'),
(81192, '블랙 스크랩포지드 메카스파이더', '연기가 자욱하고, 불꽃이 튀고, 시끄럽다.'),
(81193, '블루 스크랩포지드 메카스파이더', '엔진 경고등은 항상 켜져 있습니다. 경고등이 꺼졌을 때가 바로 걱정해야 할 상황입니다.'),
(81194, '녹색 스크랩포지드 메카스파이더', '이 기계 거미는 드릴링, 클램핑, 그리고 사격을 동시에 수행하는 데 특화되어 있습니다. 전형적인 노움 발명품이죠.'),
(81195, '레드 스크랩포지드 메카스파이더', '당신의 짜릿한 라이딩을 위해, 네 발 달린 파괴의 기계가 탄생했습니다.'),
(81198, '장갑 썬더 블러프 코도', '무리의 우두머리인 이 코도는 멀고어를 휩쓸고 다니는 위풍당당한 동물들의 대표적인 예입니다.'),
(81199, '조상의 전쟁 토템', '우리 선조들이 조각한 것입니다.'),
(81203, '바이올렛 아이 타바드', '신뢰는 얻었고, 비밀은 지켜졌습니다.\\N'),
(81204, '일리다리 타바드', '일리단의 표식을 새긴 이 휘장에는 힘과 위협이 함께 깃들어 있습니다.\\N'),
(81205, '발견의 타바드', '햇빛이 비치지 않는 곳으로 용감하게 나아가자!'),
(81206, '어둠 순찰자 [하이 엘프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81207, '달라란 구름 패밀리어', '달라란 출신의 마법사들은 언제나 진지해 보이지만, 감정을 담은 소환수들을 통해 메시지를 전달할 때는 그 모습이 사뭇 달라집니다.'),
(81208, '좀비 [트롤]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81209, '블러드 엘프 [하이 엘프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81210, '죽음의 기사 [인간, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81224, '달라란 군마 (삭제됨)', '위풍당당하고 굽히지 않는 백마.'),
(81225, '갑옷을 입은 스톰윈드 군마', '가장 치열한 전장에서 벌어지는 잔혹한 백병전을 견딜 수 있도록 훈련받았습니다.'),
(81226, '갑옷불곰', '아마니 트롤들은 곰 신 날로락을 숭배하는 방법으로 이 사나운 탈것들을 마법 부적과 의식용 가면으로 장식합니다.'),
(81227, '줄무늬 던세이버', '나이트 엘프들은 한때 야생에서 이처럼 밝은 색깔의 사브르 품종을 보는 것이 불길한 징조라고 믿었습니다.'),
(81228, '타우렌 정령 방랑자 [타우렌]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81229, '죽음의 기사 [드워프, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81230, '강령술사 III [노움]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81231, '길들여진 라크시리', '이 사나운 품종을 길들이려면 인내심, 힘, 그리고 많은 양의 가짜 쥐와 끈이 필요합니다.'),
(81232, '아주르 프로스트세이버', '점이나 줄무늬가 없다는 점은 이 짐승이 가장 오래된 서리검 계통의 후손임을 나타냅니다.'),
(81233, '철제 제련소의 장갑 램', '와일드해머 팩트 체커는 이 특정 품종이 드워프들이 던 모로그에 정착했을 때 길들인 최초의 숫양 종류라고 주장합니다.'),
(81234, '브루페스트 램', '브루어스는 대도시에서 이 탈것이 "너무 변덕스러워서 통제하기 어렵다"는 불만이 제기된 후, 광고용 탈것 사용을 중단했습니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(81235, '장갑 버밀리온 데스차저', '어떤 말들은 그저 어둠에 익숙해질 뿐이지만, 이 말은 어둠 속에서 태어났다.'),
(81236, '갑옷을 입은 회색 말', '동맹군이 치른 가장 치열한 전투들에 참전했던 베테랑.'),
(81237, '족장의 코도', '이 의식용 복장을 갖춘 코도는 보통 부족장에게만 주어지지만, 타우렌이 호드에 합류한 이후로는 썬더블러프의 용사들도 사용할 수 있게 되었습니다.'),
(81238, '터보차저 비행기', '오직 최고의 재능을 가진 엔지니어들만이 안정성과 안전성을 자랑하는 비행기를 만들어낼 용기와 정신력을 갖고 있습니다. 거기에 터보차저까지 다는 건 정말 미친 짓이죠!'),
(81239, '행복한 윔지셔 구름', '아제로스에서 가장 솜털 같은 작은 구름.'),
(81240, '슬픈 윔지셔 구름', '지금 하늘에는 해가 떠 있는데, 아무 이유 없이 슬픈 구름이 눈물을 흘리며 사라지고 있다.'),
(81241, '갑옷을 입은 오그리마 늑대', '호드의 늑대들은 길들여진 것이 아니라 친구로 여겨진다.'),
(81242, '비리디안 히포그리프', '고대 하이본족의 탈것이었던 이들은 이제 야생으로 방치되어 잠재된 마법적인 힘 때문에 찾아보기 매우 드뭅니다.'),
(81243, '부리', '와일드해머 드워프들이 얼라이언스 영웅들에게 선물한 이 새끼 그리핀들은 팔스타드와 그의 일행이 그림 바톨로 향할 때 탔던 그리핀의 후손입니다.'),
(81244, '장갑 에본 데스차저', '어떤 말들은 그저 어둠에 익숙해질 뿐이지만, 이 말은 어둠 속에서 태어났다.'),
(81245, '장갑 크림슨 데스차저', '어떤 말들은 그저 어둠에 익숙해질 뿐이지만, 이 말은 어둠 속에서 태어났다.'),
(81246, '장갑 에메랄드 데스차저', '어떤 말들은 그저 어둠에 익숙해질 뿐이지만, 이 말은 어둠 속에서 태어났다.'),
(81247, '장갑 상아 데스차저', '어떤 말들은 그저 어둠에 익숙해질 뿐이지만, 이 말은 어둠 속에서 태어났다.'),
(81248, '핀 더 샤크', '바닷속 세상을 탐험하고 싶다면 크고 안전한 이 제품은 당신 곁에 꼭 필요한 동반자가 되어줄 것입니다.'),
(81250, '강화형 블랙파운더', '가장 혹독한 전투도 견딜 수 있도록 제작된 무시무시한 전쟁 기계.'),
(81251, '강화된 블루 파운더', '가장 혹독한 전투도 견딜 수 있도록 제작된 무시무시한 전쟁 기계.'),
(81252, '강화된 그린 파운더', '가장 혹독한 전투도 견딜 수 있도록 제작된 무시무시한 전쟁 기계.'),
(81253, '강화 레드파운더', '바퀴 달린 불타는 지옥처럼, 멈추지 않는 분노로 가는 길에 있는 모든 것을 집어삼킨다.'),
(81254, '물결치는 물', '이 정령은 유황의 불의 군주들과 싸우는 데 도움을 주신 데 대한 감사의 표시로 하이드락시스 공작이 직접 제작한 것입니다.'),
(81255, '드레드스컬 [오크, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(81257, '강령술 기초 가이드', '해골을 키우는 101가지 방법.'),
(81258, '스펙트럴 큐브', '애정이 넘치고 호기심 많은 이 새끼 고양이들은 아주 특이한 곳에 숨는 재주가 있는 것 같습니다.'),
(81263, '잃어버린 어둠의 철 사슬', '체인 고리에 T.S.라는 이니셜이 새겨져 있습니다.'),
(81278, '그놈 확대 밤', '좀 더 대담해지고 싶을 때! 다른 종족에게는 예측할 수 없는 영향을 미칩니다.'),
(81283, '빅글스워스 씨', '얼어붙은 낙스라마스의 공동묘지를 빠져나오자마자, 비글스워스 씨는 곧바로 햇볕이 잘 드는 따뜻한 곳을 찾아 긴 낮잠을 즐겼다.'),
(81284, '제플린 화물', '추락 사고에서 비교적 온전하게 살아남은 것 같습니다... 대부분은요.'),
(81285, '석유 한 배럴', '더스트왈로우 습지의 진흙으로 가득 차 있다.'),
(81289, '달라란 타바드', '찬란했던 마법의 유물입니다.\\N'),
(81291, '라즐릭의 도구', '작고, 조잡하고, 기름때가 묻어있는 걸 보니 틀림없이 고블린이 만든 것 같군.'),
(81296, '스파크워터 스페셜', '냄새가 엄청나게 강하고 역겹다.'),
(81297, '그노메레간 기어', '노움족이 만든 정교한 톱니바퀴로, 마모와 손상 흔적이 뚜렷하게 보인다.'),
(81298, '진짜 드래곤 클로', '맹금류의 발톱처럼 생겼지만, 난쟁이를 후려칠 만큼 크네요!'),
(81299, '"킬로그의" 눈', '그저 눈일 뿐인데, 어디서 나온 건지 누가 알겠어요?'),
(81300, '고대 트롤 석판', '닳아빠진 돌 표면에 새겨진 트롤어.'),
(81301, '텔아빔 모래', '모래는 거칠고 작은 돌멩이가 꽤 많이 섞여 있습니다.'),
(81302, '제3차 세계 대전 보병 휘장', '마른 피가 묻은 오래된 상징물. 깨지고 닳아빠졌다.'),
(81303, '\'엘룬의 조각\'', '행운, 권력, 에너지를 가져다준다고 전해지는 작고 빛나는 돌 조각!'),
(81304, '\'아즈샤라 여왕의 왕관\'', '녹색 보석이 박힌 단순한 은색 왕관으로, 약간 세월의 흔적이 있으며 표면에 몇 군데 흠집이 있습니다.'),
(81305, '녹슨 톱니망치', '기름칠 좀 하면 좋겠네요.'),
(81306, '석유 유출 부츠', '표면이 휘발유로 덮여 있어 미끄러움을 더하고 쉽게 불이 붙도록 되어 있습니다.'),
(81307, '저주받은 고서', '먼지 쌓인 책 한 권, 알아보기 힘든 글씨로 휘갈겨 쓴 글들. 책을 오래도록 바라볼수록 마음이 설레는 것을 느낄 수 있다.'),
(81308, '썬더 리자드의 가죽', '정전기로 가득 차 있어요!'),
(81309, '팅커러의 기계식 화염 발사기', '화염구를 발사할 수 있는 복잡하고 강력한 고블린 기계 장치!'),
(81310, '백워터 브루저의 흉갑', '이곳은 전성기를 훨씬 지났는데, 그 시절에는 대부분 질서를 유지하는 데 힘썼습니다.'),
(81311, '기술자용 서보쉴드', '스파크 방지 기능이 있으며 내구성이 뛰어납니다!'),
(81320, '딱딱거리는 재퍼', '정말 큰 벌레들을 위해서요.'),
(81321, '프릭스의 목걸이', '이건 영락없는 불운의 징조야.'),
(81334, '솔트 투스의 머리', '\'짠맛\'을 느끼는 이빨은 없는 것 같네요.'),
(81336, '타를로의 상자', '윗부분에 메모가 붙어 있습니다.'),
(81337, '바위 정령 숙련: 도감 III', '바위 정령에 관한 크고 지나치게 두꺼운 책.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(81338, '물의 직조와 명령', '이 큰 책은 엄청나게 오래된 것처럼 보입니다.'),
(81339, '브라이트워터 커틀러스', '금빛 손잡이에는 작은 옥이 박혀 있다.'),
(81340, '그린포 메달리온', '더 나은 날들을 상징하는 것'),
(81345, '브라이트워터 로그북', '흠뻑 젖었어.'),
(81349, '스퀴크의 새장', '성가시고 파괴적이지만, 충분한 치즈를 주면 참을 만한 동반자로 만들 수 있습니다.'),
(81350, '롱샹크', '훌륭한 생크를 만들기에 충분히 길다!'),
(81351, '전갈왕의 손아귀', '전갈왕에 대한 소문은 일부 사실입니다.'),
(81352, '사형집행인의 두건', '죽음 그 자체의 덮개'),
(81353, '사형집행인의 두건', '죽음 그 자체의 덮개'),
(81354, '신비로운 예술의 망토', '그것들은 신비로운 에너지 속에서 반짝인다.'),
(81355, '타락한 십자군 다리 보호대', '빛의 축복을 받아 불멸을 물리치다'),
(81356, '아르카나의 족쇄', '그들은 마나 속에서 ​​번쩍거린다'),
(81357, '카르나그의 낡은 머그잔', '항상 적당량의 에일이 들어있습니다!'),
(81360, '타라나스의 발톱', '낯선 에너지가 맥동하고 있다.'),
(81363, '아주르 도미네이션의 스태프', '용군단의 지팡이는 마법을 지배한다'),
(81364, '말리고스의 척도', '청룡의 모습의 비늘'),
(81365, '카그론의 레깅스', '오랜 세월의 전투로 닳고 상처투성이인.'),
(81367, '옛 호드의 단', '블랙록 부족의 상징이 새겨져 있습니다.'),
(81369, '블레이드마스터의 검', '칼날은 전쟁에 적합하도록 완벽하게 균형이 잡혀 있습니다.'),
(81371, '그나르트위스트 베스트', '순수한 펠 에너지로 둘러싸여 있습니다'),
(81373, '사티로스의 숄', '어두운 의도로 엮어졌다'),
(81374, '트릭스터의 목걸이', '어두운 기운을 내뿜는다'),
(81376, '달빛에 물든 허리띠', '달의 축복을 받아 반짝이는 빛'),
(81378, '이브닝스타 장갑', '겨울봄 수호자의 장갑'),
(81379, '달의 조각', '달빛에 강렬한 힘이 담긴 반짝임'),
(81380, '고르둔니 전쟁 하네스', '오우거의 위력을 상징하는 것'),
(81381, '이실디엔 레이-스테이브', '고귀한 자들의 유물'),
(81383, '오우거 곤봉', '권위는 제대로 한 방 먹이는 데서 나온다'),
(81384, '그루그톡의 허리띠', '오거 특유의 악취가 난다'),
(81408, '스위프트기어의 엔지니어링 설계도', '전부 알아들을 수 없는 횡설수설처럼 보인다.'),
(81410, '바르토스 엔지니어링 용품', '상자 위에 쪽지가 붙어 있습니다.'),
(81411, '진동 억제 디스크', '공학적 걸작 - 바르토스 썬더크랙'),
(81413, '마틴 코린스의 정보', '온갖 종류의 정보를 담고 있습니다.'),
(81414, '마틴이 보내지 않은 편지', '더럽긴 하지만, 밀봉된 상태입니다.'),
(81500, '선웰의 펜던트', '엘프의 고향이 파괴된 이후로 이 목걸이들은 매우 귀한 물건이 되었습니다.'),
(81501, '타살라의 부적', '모수(母樹)의 잎 하나가 펜던트 안에 담겨 있는데, 지금도 여전히 건강한 상태를 유지하고 있습니다.'),
(81502, '태양의 축복을 받은 재생의 조각', '놀라운 치유 능력을 지닌 순수한 빛의 조각.'),
(81503, '탈라시안 수호자의 목가리개', '한때 태양의 자손들을 침략자로부터 보호하기 위해 주어졌던 마법 갑옷.'),
(82001, '알렉산드로스 곶', '애쉬브링어의 등을 덮었던 해진 망토.'),
(82002, '애쉬브링어의 타바드', '빛으로 가득 차 있다.'),
(83000, '크로노분 디스플레이서', '시간의 흐름을 바꾸어 용 사냥, 다이어 몰, 줄구룹, 다크문 축제, 대족장의 축복, 펠우드에서 발생하는 유익한 세계적 효과를 중단시킵니다.'),
(83001, '슈퍼차지 크로노분 디스플레이서', '정지된 세계 효과를 복원합니다.'),
(83006, '웰 에센스', '신의 영혼의 작은 조각.'),
(83060, '조각된 분노의 토템', '타우렌족의 분노.'),
(83061, '조각된 그림토템', '노파께서 주신 선물입니다.'),
(83062, '조각된 룬토템', '고대 비문으로 장식되어 있다.'),
(83063, '블러드후프 토템', '자부심과 영광을 담아 조각했습니다.'),
(83064, '헥스드 부두 패드', '카줌보!'),
(83090, '달라란 마법사 [인간]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(83091, '서리 친화력 [인간, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(83092, '자연학자 I [나이트 엘프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(83099, '자연학자 II [나이트 엘프]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(83100, '자연학자 III [나이트 엘프, 남성 전용]', '이 토큰을 사용하면 캐릭터의 피부색만 변경되고, 헤어스타일, 머리색, 얼굴 특징은 그대로 유지됩니다.'),
(83150, '빅 터틀 와우 베어', '등에 탄 멀록 기수는 숙련된 전사입니다! 그는 Turtle WoW 커뮤니티의 자랑스러운 일원이며, 어떤 위협으로부터든 자신의 서버를 지킬 준비가 항상 되어 있습니다.'),
(83151, '블랙 스펙트럴 타이거', '이 사나운 호랑이는 어둠의 기운에 휩싸여 있어 전장에서 공포의 대상이다. 이 호랑이를 타는 자는 그림자의 힘을 구현한다고 전해진다.'),
(83152, '그린 스펙트럴 타이거', '희귀하고 찾기 힘든 탈것인 녹색 유령 호랑이는 숲의 정령들이 축복한 것이라고 전해집니다. 이 말을 타는 자는 자연과 특별한 교감을 나눌 수 있다고 합니다.'),
(83153, '아이스 랩터', '이 날렵하고 민첩한 맹금류는 북극의 혹독하고 얼음으로 뒤덮인 환경에 적응했습니다. 날카로운 발톱과 이빨 덕분에 전투에서 강력한 탈것으로 활약할 수 있습니다.'),
(83154, '갑옷을 입은 얼음 랩터', '두꺼운 얼음 갑옷으로 뒤덮인 모습은 무시무시하다. 그것을 타는 자들은 그 맹금류만큼이나 강인하다고 전해진다.'),
(83155, '붉은십자군 군마', '이는 적에게 공포심을 심어주려는 사람들이 흔히 이용하는 방식입니다.'),
(83156, '쿨 티란 군마', '쿨 티란 군마는 튼튼하고 믿음직스러운 탈것으로, 전투를 위해 길러졌으며 위험을 두려워하지 않습니다. 거대한 몸집과 힘은 전투에서 막강한 아군이 되어줍니다.'),
(83157, '그레이메인 군마', '그레이메인 차저는 길네아인의 강인함과 회복력을 상징합니다. 윤기 나는 은빛 털과 번개처럼 빠른 속도는 길네아 병사들 사이에서 가장 인기 있는 말입니다.'),
(83158, '브라운 제브라', '브라운 제브라는 빠르고 발걸음이 안정적인 말로, 가장 험난한 지형도 쉽게 헤쳐나갈 수 있습니다. 줄무늬 털과 우아한 움직임 덕분에 모험가들 사이에서 인기 있는 선택입니다.'),
(83159, '그림 토템 코도', '그림 토템 코도는 거대하고 육중한 짐승으로, 그 엄청난 크기와 힘 때문에 많은 이들이 두려워한다. 코도를 타는 자는 대지의 힘을 마음대로 다룰 수 있다고 전해진다.'),
(83224, '엥그리스 뿔', '퍼볼그 상징으로 표시되어 있으며, 부족들을 집결시키는 데 사용되었습니다.'),
(83235, '고대 잠금 장치', '그 룬 문자가 무슨 뜻인지 알아볼 수가 없어요.'),
(83259, '올드 나이트후드 블레이드', '로데론의 첫 번째 기사단에 배치되었습니다.'),
(83261, '첫 번째 성경의 책', '빛의 거룩한 경전이 많이 담겨 있습니다.'),
(83263, '정의의 수갑', '정의를 실현하기 위해 만들어졌습니다.'),
(83264, '희생의 반지', '세상을 떠난 영혼들을 기리는 헌사'),
(83265, '악마 사냥꾼의 눈가리개', '앞을 보지 못하게 된다는 것은 악마적인 것을 보게 된다는 것이다.'),
(83267, '악마 사냥의 팔찌', '파괴할 힘으로 가득 차 있다.'),
(83269, '테러블레이드 글레이브', '악마의 타락을 파괴하기 위해 만들어졌습니다.'),
(83270, '3주년 기념 선물 (온라인 가입 3년차)', 'Turtle WoW가 3주년을 맞았습니다! 세계 최고의 게임 커뮤니티가 되어주셔서 진심으로 감사드립니다!'),
(83271, '맛있는 생일 케이크', '생일 축하해, 터틀 와우!'),
(83272, '미스터 테일즈', '아제로스를 여행하는 동안 도토리를 모으고 미스터 테일즈에게 아낌없는 관심과 사랑을 쏟으면, 그는 당신의 긴 여정에서 최고의 동반자가 되어줄 거예요.'),
(83274, '참드 부두 칼라', '부두 마법에 휘말리다.'),
(83277, '다크 아이언 어드벤처러 숄', '낡고 해진 이 물건은 전성기를 훨씬 지났음을 보여줍니다.'),
(83278, '애쉬 익스플로러 폴드론', '두꺼운 재로 뒤덮여 있다.'),
(83300, '릴 케이티', '생전에 켈투자드는 키린 토를 배신하고 저주받은 자들의 교단을 창설했습니다. 사후에는 스컬지를 섬기며 낙스라마스의 대군주가 되었습니다.'),
(83301, '코어 하운드 강아지', '불의 땅과 용암의 심장부에서 발견되는 코어 하운드는 우두머리 수컷인 마그마다르까지 거슬러 올라가는 혈통을 가지고 있습니다.'),
(83302, '릴 라그나로스', '무시무시한 불의 군주의 이 작은 측면을 소환하기에 너무 이른 때는 없습니다.'),
(83475, '사랑스러운 핑크 포니', '어디를 가든 기쁨과 행복을 가져다주는 사랑스러운 동반자입니다.'),
(83476, '러블리 핑크 퍼라인', '사랑스럽고 귀여운 생명체로, 보는 사람 모두를 매료시킨다.'),
(83477, '사랑스러운 핑크 탈북', '분홍색 말을 뭐라고 부르는지 아세요?\\N'),
(83481, '페일세이프 활성화 키', '시설 방어 매트릭스 무결성이 12%로 떨어졌으며, 침해가 임박했습니다.'),
(83482, '조난 신호 펄서', '울둠 시설이 손상되었습니다. 울다만으로 조난 신호를 보냅니다. UL- 심각한 오류 발생.'),
(83487, '떨어진 별의 검', '수억 년 전 떨어진 별의 잔해로 만들어졌습니다.'),
(83520, '마시멜로', '몰케레이가 가장 아끼는 말.'),
(83540, '숨겨진 천 어깨', '어깨를 드러낸 여름 스타일입니다.\\N'),
(83550, '원시의 불꽃', '불꽃이 끊임없이 흔들린다.'),
(83551, '끊임없이 변하는 돌', '마치 돌멩이가 생명력을 가진 것 같아요.'),
(83552, '녹지 않는 얼음', '얼음 덩어리는 열원에 가까워질수록 점점 더 차가워지는 것 같습니다.'),
(83553, '멈추지 않는 돌풍', '알 수 없는 힘에 의해, 바람이 마치 단단하게 움켜쥘 수 있을 것처럼 느껴진다.'),
(83554, '심연의 불꽃', '어떤 초자연적인 기운이 불꽃 주위에 감돌며 불가사의한 방식으로 불꽃을 휘감고 있다.'),
(83555, '심해 슬레이트', '그것을 보는 순간 뭔가 끔찍하게 잘못됐다는 것을 알 수 있다.'),
(83556, '심연의 바람', '유난히 무거운 구체를 손에 쥐고 있으면 감각이 무뎌진다.'),
(83557, '심연의 파도', '액체가 마치 벗어나려고 발버둥 치는 것처럼 위로 솟구쳐 오르는 것 같습니다.'),
(83570, '기술: 칼에 의해 죽다', '보복 상황에 처했을 때 공격을 더 잘 막아내는 방법에 대한 경전과 기술을 담고 있습니다.'),
(83571, '코덱스: 섀도우 멘드', '어둠 속에도 구원은 있다.'),
(83572, '그리모어: 악마의 문', '어둠의 의식들이 음울한 책 속에 봉인되어 있다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);

INSERT INTO `locales_item` (`entry`, `name_loc1`, `description_loc1`) VALUES
(84005, '붉은 명사수의 눈가리개', '남의 눈을 멀게 하는 자가 진정으로 보는 자이다.'),
(84006, '붉은십자군 깃발', '이 열정적인 성전에 헌신한 자들의 피로 흠뻑 젖어 있다.'),
(84037, '언더시티 버킷햇', '로데론 사냥꾼의 눈먼 동반자가 가장 좋아하는 씹는 장난감입니다.'),
(84038, '미니 크람푸스', '선물에 손대지 못하게 해!'),
(84039, '틴셀의 당근', '눈사람이 보여준 호의적인 제스처입니다. 어쩌면 당신은 겨울 할아버지의 나쁜 아이 명단에 오르지 않았을지도 몰라요!'),
(84040, '르 피쉬 오 쇼콜라', '인생을 바꾼 경험.'),
(84600, '블랙쏜의 블랙잭', '기원 시기는 여전히 미스터리로 남아 있다.'),
(84601, '영원의 풀', '영원의 우물을 둘러싼 풀밭조차 마법으로 가득 차 있었다.'),
(84603, '휘젓는 모래시계의 지팡이', '과거, 미래, 그리고 그 사이에 잃어버린 시간의 조각들.'),
(84605, '정체불명의 부유물', '희귀한 비밀 물고기.'),
(91780, '사랑스러운 녹색 셔츠', '중국에서 Turtle WoW 서버가 오픈한 첫 주 동안, 여러분의 성원에 감사하는 마음으로 작은 환영 선물을 드리고자 합니다!'),
(91781, '정성스럽게 포장된 선물', '중국에서 Turtle WoW 서버가 오픈한 첫 주 동안, 여러분의 성원에 감사하는 마음으로 작은 환영 선물을 드리고자 합니다!'),
(91785, '정성스럽게 포장된 선물', '중국에서 Turtle WoW 서버가 오픈한 첫 주 동안, 여러분의 성원에 감사하는 마음으로 작은 환영 선물을 드리고자 합니다!'),
(91790, '용의 해 선물', '용의 해를 맞아 터틀 와우 플레이어들에게 특별한 선물을 드립니다. 오래 기억될 추억을 만들고 게임에서도 멋진 성취를 이루세요. 용처럼 비상하며 행복한 한 해를 보내시길 바랍니다!\\N'),
(91791, '용의 해 셔츠', '용의 해를 맞아 터틀 와우 플레이어들에게 특별한 선물을 드립니다. 오래 기억될 추억을 만들고 게임에서도 멋진 성취를 이루세요. 용처럼 비상하며 행복한 한 해를 보내시길 바랍니다!\\N'),
(91793, '수수께끼의 붉은 봉투', '경이로운 짙은 진홍색 바탕에 금빛 용 무늬가 정교하게 새겨진 봉투입니다...\\N'),
(91794, '음력 설날 등불', '오른쪽 클릭하면 가족과 친구들과 새해를 즐길 수 있는 등불을 소환합니다!\\N'),
(92000, '타이니후프의 수축 밤', '자신이 이 세상에 비해 너무 크다고 느껴질 때... 다른 종족에게 예측할 수 없는 영향을 미칩니다.'),
(92001, '순간 이동의 서: 테라모어', '신비로운 지식이 깃든 낡은 고서는 마법사들에게 도시 해안으로 빠르게 이동할 수 있는 능력을 부여한다.'),
(92002, '차원문의 서: 테라모어', '마법사들이 테라모어 도시로 통하는 차원문을 만들어 동맹과 친구들을 빠르게 이동시킬 수 있도록 해주는 마법이 걸린 책.'),
(92003, '순간 이동의 서: 스토나드', '신비로운 지식이 깃든 낡은 고서는 마법사들에게 스토나드 전초기지로 신속하게 이동할 수 있는 능력을 부여한다.'),
(92004, '차원문의 서: 스토나드', '이 마법서는 그 안에 담긴 신비로운 정수를 해방시켜 마법사들이 슬픔의 늪 깊숙한 곳에 있는 스토나드 요새로 자신과 동료들을 순간 이동시키는 차원문을 소환할 수 있게 해줍니다.'),
(92010, '노블가든 에그', '노블가든에서 즐거운 시간 보내세요! 당신의 사냥이 놀라운 발견으로 이어지길 바랍니다.'),
(92011, '라벤더 봄 셔츠', '귀족의 정원 달걀 찾기에 잘 어울리는 축제용 라벤더 셔츠입니다. 토끼들이 길을 안내하게 두세요!\\N'),
(92012, '민트 스프링 셔츠', '상쾌한 민트색, 새로운 시작. 봄날 달걀 찾기나 계절을 즐기기에 딱 좋습니다.\\N'),
(92013, '핑크색 봄 셔츠', '토끼 꼬리처럼 부드러운 분홍 셔츠입니다. 귀족의 정원을 멋지게 즐기기에 완벽합니다.\\N'),
(92016, '점박이 토끼', '민첩하고 재빠르게 뛰어다니며 기묘할 만큼 우아한 몸놀림으로 아제로스 모험가들의 마음을 사로잡습니다.\\N'),
(92019, '녹색 봄 셔츠', '선명한 초록색으로 귀족의 정원 모험에 잘 어울립니다. 달걀을 찾을 때 입어 보세요!\\N'),
(92020, '클라코라의 피조물', '위대한 클라코라의 새끼입니다!'),
(92042, '가을 나무정령의 문양', '활성화하면 나무 변신이 가을 나무정령의 모습으로 바뀝니다.'),
(92043, '황금빛 나무정령의 문양', '활성화하면 나무 변신이 황금 나무정령의 모습으로 바뀝니다.'),
(92044, '메마른 나무정령의 문양', '활성화하면 나무 변신이 메마른 나무정령의 모습으로 바뀝니다.'),
(92050, '천상의 군마', '이 초자연적인 비행 탈것을 타고 별들 사이를 누비세요.'),
(92051, '인빈킵레', '아서스 메네실의 유명한 군마로, 삶에서도 죽음에서도 주인을 섬깁니다. 이 말을 타는 것 자체가 대단한 위업입니다.'),
(92052, '진홍빛 유령 호랑이', '역사가들은 드레노어가 폭발할 때 뿜어진 에너지가 세계의 동식물을 뒤틀어 이런 비물질적인 야수들이 생겨났다고 주장합니다.')
ON DUPLICATE KEY UPDATE `name_loc1` = VALUES(`name_loc1`), `description_loc1` = VALUES(`description_loc1`);
